<script setup lang="ts">
import { computed, nextTick, ref } from 'vue';
import { deepClone } from '../core/clone.ts';
import { 元素窗口 } from '../core/panel.ts';
import SplitHandle from './SplitHandle.vue';
import { useWorkspaceStore } from '../core/store.ts';
import {
  mergeVariables,
  renderDeclaration,
  renderSourceValues,
  scanVariableDefs,
  scanVariableRefs,
  排除变量,
} from '../core/variables.ts';
import { VARIABLE_CONSOLE_NAME, VARIABLE_CONSOLE_UID, type TargetPrompt } from '../types.ts';

const emit = defineEmits<{ 选中条目: [uid: string] }>();

const store = useWorkspaceStore();
const 变量关键词 = ref('');
/** 点击顶部统计即可筛选 */
const 筛选 = ref<null | 'conflict' | 'dangling' | 'unused'>(null);

/** 上半区高度占比，拖中间那根线可调 */
const 上半占比 = ref(55);

/**
 * 分隔线拖动。
 *
 * 样式【必须】用 computed 返回对象，不能在模板里写 `:style="{ flex: `${上半占比} 1 0%` }"`。
 * 模板字符串里的 ref 一旦没被正确解包，生成的就是 "[object Object] 1 0%" 这种非法 CSS，
 * 整条声明会被浏览器丢弃，元素退回内容高度 —— 上半区撑满、分隔线掉到最底部。
 * 这个坑排查了很久，别再踩。
 */
const 上半样式 = computed(() => ({ flex: `${上半占比.value} 1 0%` }));
const 下半样式 = computed(() => ({ flex: `${100 - 上半占比.value} 1 0%` }));

/** 效果预览里左侧目录选中的条目 */
const 目录选中 = ref(0);
/** 效果预览右侧内容容器，用于点目录时定位 */
const 预览容器 = ref<HTMLElement | null>(null);

/**
 * 左侧目录点某条 → 右侧滚到对应位置。
 * 用预览容器自己的 ownerDocument 查询：组件执行在酒馆主页面作用域，
 * 裸 document 是找不到面板 iframe 里的元素的。
 */
async function 跳到条目(下标: number) {
  目录选中.value = 下标;
  await nextTick();
  const 视图 = 元素窗口(预览容器.value);
  视图.document.querySelector(`[data-预览="${下标}"]`)?.scrollIntoView({ block: 'start', behavior: 'smooth' });
}



const 槽位 = computed(() => store.slot);
const 参与条目 = computed(() => 槽位.value.prompts);

const 来源 = computed(() =>
  scanVariableDefs(store.workspace.imports, 槽位.value.variables.ignoredConsolePromptIds),
);
const 引用 = computed(() => scanVariableRefs(参与条目.value));
const 合并结果 = computed(() => mergeVariables(来源.value, 引用.value, 槽位.value.variables.agreedValue));
const 有效合并 = computed(() => 排除变量(合并结果.value, 槽位.value.variables.excluded));

/** 声明条目内容：只声明变量名 */
const 声明内容 = computed(() => renderDeclaration(有效合并.value));

/** 各来源的赋值条目 */
const 值条目 = computed(() =>
  来源.value
    .map(源 => ({
      键: `${源.presetId}::${源.promptId}`,
      // 保留原控制台条目的名字，一眼看出这组值来自哪个预设
      名: 源.promptName,
      预设名: 源.presetName,
      内容: renderSourceValues(源, 有效合并.value, 槽位.value.variables.excluded),
    }))
    .filter(项 => 项.内容.trim().length > 0),
);

const 已有控制台 = computed(() => 槽位.value.prompts.some(t => t._uid === VARIABLE_CONSOLE_UID));

/** 变量名 → 状态 */
type 状态 = 'conflict' | 'dangling' | 'unused' | 'ok';
const 状态表 = computed(() => {
  const 映射 = new Map<string, 状态>();
  for (const d of 有效合并.value.ordered) 映射.set(d.name, 'ok');
  for (const n of 有效合并.value.unused) 映射.set(n, 'unused');
  for (const c of 合并结果.value.conflicts) 映射.set(c.name, 'conflict');
  for (const d of 合并结果.value.dangling) 映射.set(d.name, 'dangling');
  return 映射;
});

const 冲突表 = computed(() => new Map(合并结果.value.conflicts.map(c => [c.name, c])));

/** 上方面板展示的变量行 */
const 变量行 = computed(() => {
  const 行: { 名字: string; 值: string; 来源: string; 次数: number; 状态: 状态 }[] = [];
  const 引用表 = new Map(引用.value.map(r => [r.name, r]));

  for (const d of 有效合并.value.ordered) {
    行.push({
      名字: d.name,
      值: 槽位.value.variables.agreedValue[d.name] ?? d.value,
      来源: d.presetName || '(手动补齐)',
      次数: 引用表.get(d.name)?.count ?? 0,
      状态: 状态表.value.get(d.name) ?? 'ok',
    });
  }
  for (const d of 有效合并.value.dangling) {
    行.push({
      名字: d.name,
      值: 槽位.value.variables.agreedValue[d.name] ?? '',
      来源: '无定义',
      次数: d.refCount,
      状态: 'dangling',
    });
  }

  const kw = 变量关键词.value.trim();
  return 行.filter(r => {
    if (筛选.value && r.状态 !== 筛选.value) return false;
    if (kw && !r.名字.includes(kw)) return false;
    return true;
  });
});

const 统计 = computed(() => ({
  总数: 有效合并.value.ordered.length,
  冲突: 合并结果.value.conflicts.length,
  悬空: 有效合并.value.dangling.length,
  未用: 有效合并.value.unused.length,
  已排除: 槽位.value.variables.excluded.length,
}));

function 点统计(键: 'conflict' | 'dangling' | 'unused') {
  筛选.value = 筛选.value === 键 ? null : 键;
}

/* ============ 操作 ============ */

function 裁决(名字: string, 值: string) {
  槽位.value.variables.agreedValue = { ...槽位.value.variables.agreedValue, [名字]: 值 };
  // 裁决过的变量从「排除」里移出来，否则用户会困惑「选了值却不生效」
  槽位.value.variables.excluded = 槽位.value.variables.excluded.filter(n => n !== 名字);
  store.save();
}

function 切换排除(名字: string) {
  const 列表 = 槽位.value.variables.excluded;
  槽位.value.variables.excluded = 列表.includes(名字) ? 列表.filter(n => n !== 名字) : [...列表, 名字];
  store.save();
}

function 切换识别条目(条目标识: string) {
  const 列表 = 槽位.value.variables.ignoredConsolePromptIds;
  槽位.value.variables.ignoredConsolePromptIds = 列表.includes(条目标识)
    ? 列表.filter(i => i !== 条目标识)
    : [...列表, 条目标识];
  store.save();
}

/**
 * 写入目标：一条声明条目 + 每个来源一条赋值条目。
 * 声明条目锁定在首位（引用它的条目必须先取到变量值）。
 */
function 应用到目标() {
  const 声明: TargetPrompt = {
    id: 'var-console',
    name: VARIABLE_CONSOLE_NAME,
    enabled: true,
    role: 'system',
    content: 声明内容.value,
    position: { type: 'relative' },
    _uid: VARIABLE_CONSOLE_UID,
    _from: null,
    _origin: '',
    _mode: 'raw',
  };

  // 已存在的赋值条目先清掉，避免改名后残留
  const 值条目前缀 = 'var-values::';
  const 保留 = 槽位.value.prompts.filter(t => !t._uid.startsWith(值条目前缀) && t._uid !== VARIABLE_CONSOLE_UID);

  const 新值条目: TargetPrompt[] = 值条目.value.map(项 => ({
    id: `var-values-${项.键}`,
    name: 项.名,
    enabled: true,
    role: 'system',
    content: 项.内容,
    position: { type: 'relative' },
    _uid: `${值条目前缀}${项.键}`,
    _from: null,
    _origin: '',
    _mode: 'raw',
  }));

  槽位.value.prompts = [deepClone(声明), ...新值条目, ...保留];
  槽位.value.variables.consoleUid = VARIABLE_CONSOLE_UID;
  store.save();

  toastr.success(
    `已写入 1 条声明条目 + ${新值条目.length} 条赋值条目`,
    '预设缝合助手',
  );
  emit('选中条目', VARIABLE_CONSOLE_UID);
}
</script>

<template>
  <div class="flex flex-col flex-1 min-h-0">
    <!-- 统计条：点击即筛选 -->
    <div class="px-2.5 py-1.5 border-b border-line shrink-0 flex items-center gap-1.5 text-xs flex-wrap">
      <span
        class="px-1.5 py-0.5 rounded cursor-pointer transition-colors"
        :class="筛选 === null ? 'bg-accent text-accent-text' : 'bg-surface2 hover:bg-line'"
        title="显示全部"
        @click="筛选 = null"
      >
        变量 {{ 统计.总数 }}
      </span>
      <span
        v-if="统计.冲突"
        class="px-1.5 py-0.5 rounded cursor-pointer transition-colors text-warn"
        :class="筛选 === 'conflict' ? 'bg-warn text-accent-text' : 'bg-warn/15 hover:bg-warn/25'"
        title="点击只看初值有分歧的变量"
        @click="点统计('conflict')"
      >
        冲突 {{ 统计.冲突 }}
      </span>
      <span
        v-if="统计.悬空"
        class="px-1.5 py-0.5 rounded cursor-pointer transition-colors text-danger"
        :class="筛选 === 'dangling' ? 'bg-danger text-accent-text' : 'bg-danger/15 hover:bg-danger/25'"
        title="点击只看被引用但没有定义的变量"
        @click="点统计('dangling')"
      >
        悬空 {{ 统计.悬空 }}
      </span>
      <span
        v-if="统计.未用"
        class="px-1.5 py-0.5 rounded cursor-pointer transition-colors text-muted"
        :class="筛选 === 'unused' ? 'bg-line' : 'bg-surface2 hover:bg-line'"
        title="点击只看定义了但没有条目引用的变量"
        @click="点统计('unused')"
      >
        未用 {{ 统计.未用 }}
      </span>
      <span v-if="统计.已排除" class="text-muted">已排除 {{ 统计.已排除 }}</span>
      <span class="text-muted ml-auto">{{ 来源.length }} 个控制台</span>
    </div>

    <!-- 上半：变量清单 -->
    <div class="min-h-0 flex flex-col" :style="上半样式">
      <div class="px-2.5 py-1.5 shrink-0 flex items-center gap-2 text-[11px] bg-surface2/45 border-b border-line/50">
        <span class="text-muted">变量清单</span>
        <input v-model="变量关键词" class="flex-1 text-xs py-0.5" placeholder="搜索变量…" />
        <button v-if="筛选" class="text-muted hover:text-accent" title="清除筛选" @click="筛选 = null">
          <i class="fa-solid fa-filter-circle-xmark" />
        </button>
      </div>

      <details v-if="来源.length" class="shrink-0 border-b border-line/50">
        <summary class="px-2.5 py-1 text-[11px] text-muted cursor-pointer select-none">
          识别为控制台的条目（{{ 来源.length }}），可排除误判
        </summary>
        <div v-for="s in 来源" :key="s.promptId" class="flex items-center gap-2 px-2.5 py-0.5 text-[11px]">
          <span class="truncate flex-1">{{ s.presetName }} · {{ s.promptName }}</span>
          <span class="text-muted shrink-0">{{ s.defs.length }}</span>
          <button class="text-muted hover:text-danger shrink-0" title="排除该条目" @click="切换识别条目(s.promptId)">
            <i class="fa-solid fa-xmark" />
          </button>
        </div>
      </details>

      <div class="flex-1 min-h-0 overflow-y-auto">
        <div v-if="变量行.length === 0" class="p-3 text-xs text-muted leading-relaxed">
          <template v-if="来源.length === 0">
            没有识别到变量定义。先在「条目」轨把带变量的条目缝进目标，这里才会有内容。
            变量形如 <code class="text-accent">setvar::名字::值</code>，但要写成双花括号宏形式。
          </template>
          <template v-else-if="筛选">当前筛选下没有变量。</template>
          <template v-else>没有匹配的变量。</template>
        </div>

        <div
          v-for="行 in 变量行"
          :key="行.名字"
          class="px-2.5 py-1 border-b border-line/40 text-xs transition-colors"
          :class="[
            {
              'bg-danger/10 border-l-2 border-l-danger': 行.状态 === 'dangling',
              'bg-warn/10 border-l-2 border-l-warn': 行.状态 === 'conflict',
            },
            { 'opacity-45': 槽位.variables.excluded.includes(行.名字) },
          ]"
        >
          <div class="flex items-center gap-1.5">
            <input
              type="checkbox"
              class="shrink-0"
              :checked="!槽位.variables.excluded.includes(行.名字)"
              :title="槽位.variables.excluded.includes(行.名字) ? '已排除，不写进控制台' : '包含在控制台中'"
              @change="切换排除(行.名字)"
            />
            <span class="truncate shrink-0 max-w-36" :title="行.名字">{{ 行.名字 }}</span>

            <input
              v-if="行.状态 === 'dangling'"
              class="flex-1 text-xs py-0.5"
              placeholder="补初值…"
              :value="行.值"
              @change="裁决(行.名字, ($event.target as HTMLInputElement).value)"
            />
            <template v-else-if="行.状态 === 'conflict'">
              <div class="flex-1 flex gap-1 flex-wrap">
                <button
                  v-for="候选 in 冲突表.get(行.名字)?.candidates ?? []"
                  :key="候选.presetId"
                  class="px-1.5 py-0.5 rounded border border-line hover:border-accent text-[10px] truncate max-w-36"
                  :title="`采用「${候选.presetName}」的初值：${候选.value}`"
                  @click="裁决(行.名字, 候选.value)"
                >
                  {{ 候选.presetName }}：{{ 候选.value }}
                </button>
              </div>
            </template>
            <input
              v-else
              class="flex-1 text-xs py-0.5"
              :value="行.值"
              @change="裁决(行.名字, ($event.target as HTMLInputElement).value)"
            />
          </div>

          <div class="text-[10px] text-muted pl-5 mt-0.5 flex items-center gap-2">
            <span class="truncate">{{ 行.来源 }}</span>
            <span v-if="行.次数">被引用 {{ 行.次数 }} 次</span>
            <span v-if="行.状态 === 'unused'">未被引用</span>
            <span v-if="行.状态 === 'conflict'" class="text-warn">初值有分歧，点上方选择</span>
            <span v-if="行.状态 === 'dangling'" class="text-danger">没有定义，不补值引用它的条目会静默失效</span>
          </div>
        </div>
      </div>
    </div>
    <SplitHandle @拖动="比例 => (上半占比 = 比例)" />

    <!-- 下半：效果预览 -->
    <div class="min-h-0 flex flex-col" :style="下半样式">
      <div class="px-2.5 py-1.5 shrink-0 flex items-center gap-2 text-[11px] bg-surface2/45 border-b border-line/50">
        <span class="text-muted">效果预览</span>
        <span class="text-muted">· {{ 值条目.length + 1 }} 条条目</span>
        <button
          class="ml-auto px-2 py-0.5 rounded bg-accent text-accent-text font-medium disabled:opacity-40"
          :disabled="有效合并.ordered.length === 0"
          @click="应用到目标"
        >
          {{ 已有控制台 ? '更新目标' : '应用到目标' }}
        </button>
      </div>

      <div class="flex-1 min-h-0 flex gap-2 p-2">
        <!-- 左：条目目录 -->
        <div class="w-40 shrink-0 flex flex-col min-h-0 rounded-md border border-line overflow-hidden">
          <div class="px-2 py-1.5 shrink-0 text-[10px] text-muted bg-surface2/60 border-b border-line">条目目录</div>
          <div class="flex-1 min-h-0 overflow-y-auto">
            <button
              class="w-full text-left px-2 py-1 text-[11px] border-b border-line/40 transition-colors"
              :class="目录选中 === 0 ? 'bg-accent-soft/40 text-accent' : 'hover:bg-surface2/60'"
              title="声明条目：只放变量名，锁定首位"
              @click="跳到条目(0)"
            >
              <div class="flex items-center gap-1">
                <i class="fa-solid fa-lock text-warn text-[9px]" />
                <span class="truncate flex-1">{{ VARIABLE_CONSOLE_NAME }}</span>
              </div>
              <div class="text-[9px] text-muted pl-3.5">声明 · {{ 有效合并.ordered.length }} 个变量</div>
            </button>

            <button
              v-for="(项, i) in 值条目"
              :key="项.键"
              class="w-full text-left px-2 py-1 text-[11px] border-b border-line/40 transition-colors"
              :class="目录选中 === i + 1 ? 'bg-accent-soft/40 text-accent' : 'hover:bg-surface2/60'"
              :title="`赋值条目，来自 ${项.预设名}`"
              @click="跳到条目(i + 1)"
            >
              <div class="flex items-center gap-1">
                <i class="fa-solid fa-equals text-accent text-[9px]" />
                <span class="truncate flex-1">{{ 项.名 }}</span>
              </div>
              <div class="text-[9px] text-muted pl-3.5 truncate">来自 {{ 项.预设名 }}</div>
            </button>
          </div>
        </div>

        <!-- 右：条目内容 -->
        <div ref="预览容器" class="flex-1 min-w-0 min-h-0 overflow-y-auto space-y-2">
          <div class="rounded-md border border-warn/40 overflow-hidden" data-预览="0">
            <div class="px-2 py-1 bg-warn/10 text-[10px] flex items-center gap-1.5">
              <i class="fa-solid fa-lock text-warn" />
              <span class="truncate">{{ VARIABLE_CONSOLE_NAME }}</span>
              <span class="text-muted ml-auto">声明 · 锁定首位</span>
            </div>
            <pre class="p-2 bg-surface2/50 text-[11px] leading-relaxed whitespace-pre-wrap font-mono">{{ 声明内容 || '（没有变量）' }}</pre>
          </div>

          <div
            v-for="(项, i) in 值条目"
            :key="项.键"
            class="rounded-md border border-line overflow-hidden"
            :data-预览="i + 1"
          >
            <div class="px-2 py-1 bg-surface2 text-[10px] flex items-center gap-1.5">
              <i class="fa-solid fa-equals text-accent" />
              <span class="truncate">{{ 项.名 }}</span>
              <span class="text-muted ml-auto truncate">赋值 · 来自 {{ 项.预设名 }}</span>
            </div>
            <pre class="p-2 bg-surface2/50 text-[11px] leading-relaxed whitespace-pre-wrap font-mono">{{ 项.内容 }}</pre>
          </div>

          <p class="text-[10px] text-muted leading-relaxed">
            声明条目只放变量名（空值），实际值放在各自的赋值条目里。
            赋值条目的名字保留各来源预设原来的控制台名，方便对照。
          </p>
        </div>
      </div>
    </div>
  </div>
</template>
