import type { LegacyRegexScript, RegexConflict, RegexFieldLoss, TavernRegex } from '../types.ts';

/** 酒馆正则作用范围枚举, 抄自 scripts/extensions/regex/engine.js */
export const REGEX_PLACEMENT = {
  MD_DISPLAY: 0,
  USER_INPUT: 1,
  AI_OUTPUT: 2,
  SLASH_COMMAND: 3,
  WORLD_INFO: 5,
  REASONING: 6,
} as const;

/**
 * 酒馆原生格式 → 归一化格式。
 *
 * 与酒馆助手 tavern_regex.ts 的 to_tavern_regex 保持一致, 但额外保留 reasoning 判定,
 * 以便 detectFieldLoss 能发现该字段会在往返中丢失。
 */
export function normalizeLegacyRegex(raw: LegacyRegexScript): TavernRegex {
  const placement = raw.placement ?? [];
  return {
    id: raw.id,
    script_name: raw.scriptName,
    enabled: !raw.disabled,
    find_regex: raw.findRegex,
    trim_strings: raw.trimStrings ?? [],
    replace_string: raw.replaceString,
    source: {
      user_input: placement.includes(REGEX_PLACEMENT.USER_INPUT),
      ai_output: placement.includes(REGEX_PLACEMENT.AI_OUTPUT),
      slash_command: placement.includes(REGEX_PLACEMENT.SLASH_COMMAND),
      world_info: placement.includes(REGEX_PLACEMENT.WORLD_INFO),
      reasoning: placement.includes(REGEX_PLACEMENT.REASONING),
    },
    destination: { display: raw.markdownOnly, prompt: raw.promptOnly },
    run_on_edit: raw.runOnEdit,
    min_depth: typeof raw.minDepth === 'number' ? raw.minDepth : null,
    max_depth: typeof raw.maxDepth === 'number' ? raw.maxDepth : null,
  };
}

/**
 * 归一化格式 → 酒馆原生格式。
 * 注意: substituteRegex 只能写回 0, 酒馆助手自身也是这么做的 (它会丢失该选项)。
 */
export function toLegacyRegex(regex: TavernRegex): LegacyRegexScript {
  const p = REGEX_PLACEMENT;
  return {
    id: regex.id,
    scriptName: regex.script_name,
    disabled: !regex.enabled,
    runOnEdit: regex.run_on_edit,
    findRegex: regex.find_regex,
    trimStrings: regex.trim_strings ?? [],
    replaceString: regex.replace_string,
    placement: [
      ...(regex.source.user_input ? [p.USER_INPUT] : []),
      ...(regex.source.ai_output ? [p.AI_OUTPUT] : []),
      ...(regex.source.slash_command ? [p.SLASH_COMMAND] : []),
      ...(regex.source.world_info ? [p.WORLD_INFO] : []),
      ...(regex.source.reasoning ? [p.REASONING] : []),
    ],
    substituteRegex: 0,
    minDepth: regex.min_depth,
    maxDepth: regex.max_depth,
    markdownOnly: regex.destination.display,
    promptOnly: regex.destination.prompt,
  };
}

/**
 * 检出会在归一化往返中丢字段的正则。
 *
 * 依据: 酒馆助手 4.8.10 的 from_tavern_regex 硬编码 substituteRegex: 0,
 * 且其 source 只映射 4 个 placement (不含 reasoning)。
 * 用户当前数据没有踩到, 但换预设可能踩到, 所以显式警告而非静默丢。
 */
export function detectFieldLoss(
  regexes: TavernRegex[],
  rawById: Map<string, LegacyRegexScript>,
): RegexFieldLoss[] {
  const losses: RegexFieldLoss[] = [];
  for (const regex of regexes) {
    const raw = rawById.get(regex.id);
    if (!raw) continue;
    const reasons: string[] = [];
    if ((raw.substituteRegex ?? 0) !== 0) {
      reasons.push(`「替换宏」选项 (substituteRegex=${raw.substituteRegex}) 会在写入时被重置为 0`);
    }
    if ((raw.placement ?? []).includes(REGEX_PLACEMENT.REASONING)) {
      reasons.push('作用范围含「推理」，酒馆助手的归一化不保留该选项');
    }
    if (reasons.length > 0) losses.push({ regexId: regex.id, name: regex.script_name, reasons });
  }
  return losses;
}

/* ============ 冲突检测 ============ */

/** 去掉首尾 /flags、空白与控制差异并统一小写, 用于比较 */
function normalizePattern(findRegex: string): string {
  let s = (findRegex ?? '').trim();
  const match = s.match(/^\/([\s\S]*)\/([a-z]*)$/i);
  if (match) s = match[1];
  return s.replace(/\s+/g, '').toLowerCase();
}

/** 字符级 Levenshtein 相似度, 返回 0~1 */
export function levenshteinSimilarity(a: string, b: string): number {
  if (a === b) return 1;
  if (a.length === 0 || b.length === 0) return 0;

  let prev = new Array<number>(b.length + 1);
  let curr = new Array<number>(b.length + 1);
  for (let j = 0; j <= b.length; j++) prev[j] = j;

  for (let i = 1; i <= a.length; i++) {
    curr[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      curr[j] = Math.min(prev[j] + 1, curr[j - 1] + 1, prev[j - 1] + cost);
    }
    const swap = prev;
    prev = curr;
    curr = swap;
  }

  return 1 - prev[b.length] / Math.max(a.length, b.length);
}

/** 相似度阈值 (设计文档 §4.3) */
export const SIMILARITY_THRESHOLD = 0.8;

/** 短于此长度的模式不参与相似度比较, 否则会产生大量无意义告警 */
const MIN_PATTERN_LENGTH = 8;

/**
 * 检测正则冲突。
 *
 * 只报告不阻断 —— 正则的顺序由用户通过拖拽决定, 谁赢谁输是用户的选择。
 */
export function detectRegexConflicts(regexes: TavernRegex[]): RegexConflict[] {
  const conflicts: RegexConflict[] = [];

  // 1. 查找表达式完全相同
  const byPattern = new Map<string, TavernRegex[]>();
  for (const regex of regexes) {
    const key = normalizePattern(regex.find_regex);
    const list = byPattern.get(key) ?? [];
    list.push(regex);
    byPattern.set(key, list);
  }
  for (const list of byPattern.values()) {
    if (list.length > 1) {
      conflicts.push({
        type: 'exact_duplicate',
        regexIds: list.map(r => r.id),
        names: list.map(r => r.script_name),
      });
    }
  }

  // 2. 高度相似 (排除已判定为完全相同的)
  const exactIds = new Set(
    conflicts.flatMap(c => (c.type === 'exact_duplicate' ? c.regexIds : [])),
  );
  const remaining = regexes
    .filter(r => !exactIds.has(r.id))
    .map(r => ({ regex: r, pattern: normalizePattern(r.find_regex) }));

  for (let i = 0; i < remaining.length; i++) {
    for (let j = i + 1; j < remaining.length; j++) {
      const a = remaining[i];
      const b = remaining[j];
      if (a.pattern.length < MIN_PATTERN_LENGTH || b.pattern.length < MIN_PATTERN_LENGTH) continue;
      const similarity = levenshteinSimilarity(a.pattern, b.pattern);
      if (similarity >= SIMILARITY_THRESHOLD) {
        conflicts.push({
          type: 'similar',
          regexIds: [a.regex.id, b.regex.id],
          names: [a.regex.script_name, b.regex.script_name],
          similarity,
        });
      }
    }
  }

  // 3. 作用域重叠 (来源与用途完全一致, 且都启用)
  const byScope = new Map<string, TavernRegex[]>();
  for (const regex of regexes) {
    const sourceKey = [
      regex.source.user_input,
      regex.source.ai_output,
      regex.source.slash_command,
      regex.source.world_info,
    ].join(',');
    const key = `${sourceKey}|${regex.destination.display}|${regex.destination.prompt}`;
    const list = byScope.get(key) ?? [];
    list.push(regex);
    byScope.set(key, list);
  }
  for (const list of byScope.values()) {
    const active = list.filter(r => r.enabled);
    if (active.length > 1) {
      conflicts.push({
        type: 'scope_overlap',
        regexIds: active.map(r => r.id),
        names: active.map(r => r.script_name),
      });
    }
  }

  return conflicts;
}
