<script setup lang="ts">
/**
 * 预设缝合助手 · 手机版外壳。
 *
 * 与桌面版的唯一区别是布局：
 * 桌面版是三栏并排，手机版把所有切换都收到顶部，内容单列堆叠。
 * 核心逻辑（core/）与各功能面板（components/）与桌面版完全共用，
 * 所以两边功能一致、修一处两边都好。
 */
import { computed, inject, onMounted, watch, ref } from 'vue';
import AiAssistant from '../预设缝合助手/components/AiAssistant.vue';
import GlobalParams from '../预设缝合助手/components/GlobalParams.vue';
import PresetPanel from '../预设缝合助手/components/PresetPanel.vue';
import PromptEditor from '../预设缝合助手/components/PromptEditor.vue';
import RegexEditor from '../预设缝合助手/components/RegexEditor.vue';
import SourcePromptList from '../预设缝合助手/components/SourcePromptList.vue';
import SourceRegexList from '../预设缝合助手/components/SourceRegexList.vue';
import TargetPromptList from '../预设缝合助手/components/TargetPromptList.vue';
import TargetRegexList from '../预设缝合助手/components/TargetRegexList.vue';
import VariableTable from '../预设缝合助手/components/VariableTable.vue';
import { 同步槽位, 导入槽位为源预设 } from '../预设缝合助手/core/actions.ts';
import { useWorkspaceStore } from '../预设缝合助手/core/store.ts';
import type { PresetPrompt, TavernRegex } from '../预设缝合助手/types.ts';

const 关闭面板 = inject<() => void>('关闭面板', () => {
  console.warn('[预设缝合助手] 未注入关闭能力');
});
const 面板文档 = inject<Document | null>('面板文档', null);

const store = useWorkspaceStore();

/* ============ 顶部页签 ============ */

const 页签 = ref<'预设' | '条目' | '变量' | '正则' | 'AI'>('预设');

const 页签表 = computed(() => [
  { key: '预设' as const, 名: '预设', 数: store.workspace.imports.length },
  { key: '条目' as const, 名: '条目', 数: store.slot.prompts.length },
  { key: '变量' as const, 名: '变量', 数: 0 },
  { key: '正则' as const, 名: '正则', 数: store.slot.regexes.length },
  { key: 'AI' as const, 名: 'AI', 数: 0 },
]);

/** 条目 / 正则页签里的子分段：源 → 目标 → 编辑 */
const 子段 = ref<'源' | '目标' | '编辑'>('源');

/**
 * AI 页签里的子分段。
 * 必须有：AI 助手有两套能力（抓条目 / 筛正则），
 * 只给一个入口的话「AI 筛选正则」在手机上就够不着了。
 */
const AI子段 = ref<'条目' | '正则'>('条目');

/** 切页签时，条目/正则回到「源」，避免停在空的编辑页 */
watch(页签, 值 => {
  if (值 === '条目' || 值 === '正则') 子段.value = '源';
});

/* ============ 槽位 ============ */

const 槽位菜单 = ref(false);

function 选槽位(id: string) {
  store.切换槽位(id);
  槽位菜单.value = false;
}

function 新建槽位() {
  store.新建槽位();
  槽位菜单.value = false;
}

function 槽位操作(动作: '重命名' | '同步' | '导入' | '删除') {
  const id = store.slot.id;
  槽位菜单.value = false;
  if (动作 === '重命名') {
    const 名 = prompt('槽位名称（也是同步到酒馆时的预设名）', store.slot.name);
    if (名 !== null) store.重命名槽位(id, 名.trim());
  } else if (动作 === '同步') {
    同步槽位(store, id);
  } else if (动作 === '导入') {
    const 新id = 导入槽位为源预设(store, id);
    if (新id) 当前预设.value = 新id;
  } else {
    store.删除槽位(id);
  }
}

/* ============ 主题 ============ */

function 应用主题() {
  if (!面板文档) return;
  面板文档.documentElement.dataset.theme = store.workspace.theme;
}
watch(() => store.workspace.theme, 应用主题);
onMounted(应用主题);

/* ============ 交互 ============ */

const activePresetId = ref<string | null>(null);
const 选中条目uid = ref<string | null>(null);
const 正则索引 = ref<number | null>(null);
const 源批量模式 = ref(false);
const 同步中 = ref(false);

function 加入目标(prompt: PresetPrompt, presetId: string) {
  store.切换目标条目(prompt, presetId);
}

function 加入正则(regex: TavernRegex) {
  store.切换目标正则(regex);
}

/** 核弹级操作，必须二次确认 */
function 清空全部() {
  槽位菜单.value = false;
  const 确认 = confirm('确定要清空全部数据吗？将删除：所有已导入的源预设、所有缝合槽位及其目标条目与正则、AI 助手的输入与自定义提示词。此操作无法撤销。');
  if (!确认) return;
  store.清空全部();
  选中条目uid.value = null;
  正则索引.value = null;
  activePresetId.value = null;
  toastr.success('已清空全部数据', '预设缝合助手');
}

async function 执行同步() {
  同步中.value = true;
  try {
    await 同步槽位(store, store.slot.id);
  } finally {
    同步中.value = false;
  }
}
</script>

<template>
  <div class="h-screen w-screen flex flex-col text-body overflow-hidden">
    <!-- 顶栏：标题 + 槽位 + 主题 + 关闭 -->
    <header class="glass-strong shrink-0 px-2 py-1.5 flex items-center gap-2">
      <i class="fa-solid fa-blender text-accent" />

      <!-- 槽位（手机上用下拉，省横向空间） -->
      <button
        class="flex-1 min-w-0 text-left px-2 py-1 rounded-md border border-line text-xs flex items-center gap-1"
        @click.stop="槽位菜单 = !槽位菜单"
      >
        <span class="truncate flex-1">{{ store.slot.name || '未命名槽位' }}</span>
        <span class="text-muted shrink-0">{{ store.slot.prompts.length }}条</span>
        <i class="fa-solid fa-caret-down text-[10px] opacity-60 shrink-0" />
      </button>

      <button
        class="shrink-0 w-8 h-8 rounded-md border border-line flex items-center justify-center"
        :title="store.workspace.theme === 'dark' ? '切到日间' : '切到夜间'"
        @click.stop="store.切换主题()"
      >
        <i :class="store.workspace.theme === 'dark' ? 'fa-solid fa-sun' : 'fa-solid fa-moon'" />
      </button>

      <button
        class="shrink-0 w-8 h-8 rounded-md border border-line flex items-center justify-center"
        @click="关闭面板()"
      >
        <i class="fa-solid fa-xmark" />
      </button>
    </header>

    <!-- 第二行：所有界面切换都在这里 -->
    <nav class="shrink-0 flex gap-1 px-2 py-1.5 overflow-x-auto glass border-b border-line">
      <button
        v-for="项 in 页签表"
        :key="项.key"
        class="shrink-0 px-3 py-1.5 rounded-md text-xs transition-colors flex items-center gap-1"
        :class="页签 === 项.key ? 'bg-accent text-accent-text font-medium' : 'bg-surface/60 hover:bg-surface2'"
        @click="页签 = 项.key"
      >
        {{ 项.名 }}
        <span v-if="项.数" class="opacity-75">{{ 项.数 }}</span>
      </button>
    </nav>

    <!-- 子分段：条目 / 正则 页签内的 源→目标→编辑 -->
    <div
      v-if="页签 === 'AI'"
      class="shrink-0 flex gap-1 px-2 py-1.5 border-b border-line"
    >
      <button
        v-for="段 in ['条目', '正则'] as const"
        :key="段"
        class="flex-1 py-1.5 rounded-md text-xs transition-colors"
        :class="AI子段 === 段 ? 'bg-accent-soft/60 text-accent font-medium' : 'bg-surface/50 hover:bg-surface2'"
        @click="AI子段 = 段"
      >
        <i :class="段 === '条目' ? 'fa-solid fa-list' : 'fa-solid fa-code'" class="mr-1" />{{ 段 }}
      </button>
    </div>

    <div
      v-else-if="页签 === '条目' || 页签 === '正则'"
      class="shrink-0 flex gap-1 px-2 py-1.5 border-b border-line"
    >
      <button
        v-for="段 in ['源', '目标', '编辑'] as const"
        :key="段"
        class="flex-1 py-1.5 rounded-md text-xs transition-colors"
        :class="子段 === 段 ? 'bg-accent-soft/60 text-accent font-medium' : 'bg-surface/50 hover:bg-surface2'"
        @click="子段 = 段"
      >
        <i
          :class="
            段 === '源'
              ? 'fa-solid fa-arrow-down-long'
              : 段 === '目标'
                ? 'fa-solid fa-list'
                : 'fa-solid fa-pen-to-square'
          "
          class="mr-1"
        />{{ 段 === '源' ? '待选' : 段 }}
      </button>
    </div>

    <!-- 内容区（单列，全宽全高） -->
    <main class="flex-1 min-h-0 flex flex-col">
      <!-- 预设页签 -->
      <template v-if="页签 === '预设'">
        <div class="flex-[3] min-h-0 flex flex-col glass">
          <PresetPanel
            v-model:批量模式="源批量模式"
            @选中预设="
              activePresetId = $event;
              页签 = '条目';
              子段 = '源';
            "
          />
        </div>
        <div class="h-px shrink-0 bg-line-strong/45 mx-3" />
        <div class="flex-[2] min-h-0 flex flex-col glass">
          <GlobalParams />
        </div>
      </template>

      <!-- 条目页签 -->
      <template v-else-if="页签 === '条目'">
        <div class="flex-1 min-h-0 flex flex-col glass">
          <SourcePromptList
            v-if="子段 === '源'"
            v-model:批量模式="源批量模式"
            :preset-id="activePresetId"
            @选择="加入目标"
          />
          <TargetPromptList
            v-else-if="子段 === '目标'"
            :选中-uid="选中条目uid"
            @选中="
              选中条目uid = $event;
              子段 = '编辑';
            "
          />
          <PromptEditor v-else :uid="选中条目uid" />
        </div>
      </template>

      <!-- 变量页签 -->
      <template v-else-if="页签 === '变量'">
        <div class="flex-1 min-h-0 flex flex-col glass">
          <VariableTable @选中条目="选中条目uid = $event; 页签 = '条目'; 子段 = '编辑'" />
        </div>
      </template>

      <!-- 正则页签 -->
      <template v-else-if="页签 === '正则'">
        <div class="flex-1 min-h-0 flex flex-col glass">
          <SourceRegexList v-if="子段 === '源'" @选中="加入正则" />
          <TargetRegexList
            v-else-if="子段 === '目标'"
            @选中编辑器="
              i => {
                正则索引 = i;
                子段 = '编辑';
              }
            "
          />
          <RegexEditor v-else :index="正则索引" />
        </div>
      </template>

      <!-- AI 页签 -->
      <template v-else>
        <div class="flex-1 min-h-0 flex flex-col glass">
          <AiAssistant :track="AI子段 === '正则' ? 'regex' : 'entry'" />
        </div>
      </template>
    </main>

    <!-- 底部固定操作条 -->
    <footer class="glass-strong shrink-0 px-2 py-1.5 flex items-center gap-2 border-t border-line">
      <span class="text-[11px] text-muted truncate flex-1">
        骨架
        <span :class="store.skeleton ? 'text-accent' : 'text-danger'">
          {{ store.skeleton?.name ?? '未选' }}
        </span>
      </span>
      <button
        class="shrink-0 px-4 py-2 rounded-md bg-accent text-accent-text font-medium text-xs disabled:opacity-40"
        :disabled="同步中"
        @click="执行同步"
      >
        {{ 同步中 ? '同步中…' : '同步并启用' }}
      </button>
    </footer>

    <!-- 槽位菜单 -->
    <template v-if="槽位菜单">
      <div class="fixed inset-0 z-40" @click="槽位菜单 = false" />
      <div class="fixed left-2 right-2 top-14 z-50 glass-strong rounded-lg p-2 space-y-1 text-xs">
        <div class="text-[10px] text-muted px-1 pb-1 border-b border-line">缝合槽位</div>
        <button
          v-for="项 in store.workspace.slots"
          :key="项.id"
          class="w-full text-left px-2 py-2 rounded-md flex items-center gap-2"
          :class="项.id === store.slot.id ? 'bg-accent-soft/50 text-accent' : 'hover:bg-surface2'"
          @click="选槽位(项.id)"
        >
          <i class="fa-solid fa-layer-group" />
          <span class="truncate flex-1">{{ 项.name || '未命名' }}</span>
          <span class="text-muted">{{ 项.prompts.length }} / {{ 项.regexes.length }}</span>
        </button>

        <div class="border-t border-line my-1" />
        <div class="text-[10px] text-muted px-1 pb-1">对当前槽位操作</div>
        <div class="grid grid-cols-2 gap-1">
          <button class="px-2 py-2 rounded-md border border-line hover:border-accent" @click="槽位操作('重命名')">
            <i class="fa-solid fa-pen mr-1" />重命名
          </button>
          <button class="px-2 py-2 rounded-md border border-line hover:border-accent" @click="槽位操作('同步')">
            <i class="fa-solid fa-upload mr-1" />同步到酒馆
          </button>
          <button class="px-2 py-2 rounded-md border border-line hover:border-accent" @click="槽位操作('导入')">
            <i class="fa-solid fa-circle-down mr-1" />导入为素材
          </button>
          <button
            class="px-2 py-2 rounded-md border border-line hover:border-danger hover:text-danger disabled:opacity-40"
            :disabled="store.workspace.slots.length <= 1"
            @click="槽位操作('删除')"
          >
            <i class="fa-solid fa-trash-can mr-1" />删除槽位
          </button>
        </div>

        <div class="border-t border-line my-1" />
        <div class="grid grid-cols-2 gap-1">
          <button class="px-2 py-2 rounded-md border border-dashed border-line-strong hover:border-accent" @click="新建槽位">
            <i class="fa-solid fa-plus mr-1" />新建槽位
          </button>
          <button
            class="px-2 py-2 rounded-md border border-line hover:border-danger hover:text-danger"
            @click="清空全部"
          >
            <i class="fa-solid fa-trash-can mr-1" />清空全部
          </button>
        </div>
      </div>
    </template>
  </div>
</template>
