/**
 * 本项目自建类型定义。
 *
 * 为什么不用模板 @types 里的全局 Preset 类型：
 * 模板 @types/function/preset.d.ts 把 extensions.tavern_helper.variables 误拼为 variales，
 * 与酒馆助手 4.8.10 真实源码 (src/function/preset.ts) 不符。自建以免类型欺骗。
 */

/** 酒馆助手的归一化提示词条目 */
export type PresetPrompt = {
  id: string;
  name: string;
  enabled: boolean;
  position?: { type: 'relative' } | { type: 'in_chat'; depth: number; order: number };
  role: 'system' | 'user' | 'assistant';
  content?: string;
  extra?: Record<string, any>;
};

/** 酒馆助手的归一化正则条目 */
export type TavernRegex = {
  id: string;
  script_name: string;
  enabled: boolean;
  find_regex: string;
  replace_string: string;
  trim_strings: string[];
  source: {
    user_input: boolean;
    ai_output: boolean;
    slash_command: boolean;
    world_info: boolean;
    reasoning?: boolean;
  };
  destination: { display: boolean; prompt: boolean };
  run_on_edit: boolean;
  min_depth: number | null;
  max_depth: number | null;
};

/** 酒馆助手的归一化预设 */
export type Preset = {
  settings: Record<string, any>;
  prompts: PresetPrompt[];
  prompts_unused: PresetPrompt[];
  extensions: Record<string, any>;
};

/** 酒馆原生格式的正则脚本 (旧格式, 用于导入独立的正则 json) */
export type LegacyRegexScript = {
  id: string;
  scriptName: string;
  findRegex: string;
  replaceString: string;
  trimStrings?: string[];
  placement: number[];
  disabled: boolean;
  markdownOnly: boolean;
  promptOnly: boolean;
  runOnEdit: boolean;
  substituteRegex?: number;
  minDepth: number | null;
  maxDepth: number | null;
};

export type EntryKind = 'normal' | 'system' | 'placeholder';

export type ImportedPreset = {
  id: string;
  name: string;
  source: 'tavern' | 'file';
  raw: Preset;
  importedAt: number;
};

export type TargetPrompt = PresetPrompt & {
  _uid: string;
  _from: { presetId: string; promptId: string } | null;
  _origin: string;
  _mode: 'raw' | 'aligned' | 'merged';
};

export type EntryConflict =
  | { type: 'duplicate_system'; uid: string; id: string }
  | { type: 'duplicate_placeholder'; uid: string; id: string }
  | { type: 'same_depth'; uids: string[]; depth: number }
  | { type: 'duplicate_name'; uids: string[]; name: string };

export type VarDef = {
  name: string;
  value: string;
  presetId: string;
  presetName: string;
  promptId: string;
  promptName: string;
  seq: number;
  group: string | null;
};

export type VarConflict = {
  name: string;
  candidates: { presetId: string; presetName: string; value: string }[];
};

export type DanglingVar = { name: string; refCount: number };

export type VarRef = { name: string; count: number; uids: string[] };

/** 一个变量定义条目在源预设中的定位 */
export type VarConsoleSource = {
  presetId: string;
  presetName: string;
  promptId: string;
  promptName: string;
  defs: VarDef[];
};

export type RegexConflict =
  | { type: 'exact_duplicate'; regexIds: string[]; names: string[] }
  | { type: 'similar'; regexIds: string[]; names: string[]; similarity: number }
  | { type: 'scope_overlap'; regexIds: string[]; names: string[] }
  | { type: 'field_loss_risk'; regexIds: string[]; names: string[]; reason: string };

export type RegexSourceEntry = {
  presetId: string;
  presetName: string;
  regex: TavernRegex;
};

export type RegexFieldLoss = {
  regexId: string;
  name: string;
  reasons: string[];
};

/**
 * 一个缝合槽位。
 *
 * 每个槽位是一份独立的缝合产出：自己的骨架、自己的目标条目、自己的变量裁决与正则。
 * 导入的源预设（imports）是所有槽位共享的素材库，不属于任何槽位。
 */
export type StitchSlot = {
  id: string;
  /** 同步到酒馆时使用的预设名 */
  name: string;
  skeletonId: string | null;
  /**
   * 用户手动覆盖的全局生成参数（键为参数表里的显示名）。
   * 为空则沿用骨架预设自带的参数 —— 有些骨架预设（如实测的剧作家预设）根本不带参数，
   * 这时就必须靠这里设定。
   */
  paramsOverride: Record<string, number | boolean>;
  /** 目标条目的唯一真相源。不额外维护 uid 列表，避免两处状态不同步 */
  prompts: TargetPrompt[];
  variables: {
    /** 冲突变量的裁决值：变量名 → 用户选定的初值 */
    agreedValue: Record<string, string>;
    /** 被用户手动排除、不写进控制台的变量名 */
    excluded: string[];
    /** 被判定为变量控制台的源条目 id（用户可手动排除误判） */
    ignoredConsolePromptIds: string[];
    /** 变量控制台在目标栏里的 uid */
    consoleUid: string | null;
    renderTemplate: string;
  };
  regexes: TavernRegex[];
};

export type Workspace = {
  version: 2;
  imports: ImportedPreset[];
  slots: StitchSlot[];
  activeSlotId: string | null;
  /** 主题：夜 = 深蓝，日 = 暖黄 + 浅绿 */
  theme: 'dark' | 'light';
  ai: {
    keyword: string;
    /** 作为 AI 固定参照注入的目标条目 uid */
    injectionUids: string[];
    /**
     * 只在哪些源预设里搜索。空数组 = 全部导入的预设。
     * 导入的预设多了以后，限定范围能显著缩短粗筛时间并提高准确度。
     */
    selectedPresetIds: string[];
    /** 用户可覆盖的系统提示词。空字符串表示用内置默认值 */
    prompts: { filter: string; rewrite: string; regex: string };
  };
};

/* ============ 事实常量 ============ */

/** 变量控制台在目标栏中的固定 uid */
export const VARIABLE_CONSOLE_UID = 'var-console::控制台';

/** 变量控制台的默认条目名 */
export const VARIABLE_CONSOLE_NAME = '📜缝合变量控制台';

export const SYSTEM_PROMPT_IDS = ['main', 'nsfw', 'jailbreak', 'enhanceDefinitions'] as const;

export const PLACEHOLDER_IDS = [
  'worldInfoBefore',
  'personaDescription',
  'charDescription',
  'charPersonality',
  'scenario',
  'worldInfoAfter',
  'dialogueExamples',
  'chatHistory',
] as const;

/** 这两个占位符在酒馆助手的往返中不带 position 字段 */
export const POSITIONLESS_PLACEHOLDER_IDS = ['dialogueExamples', 'chatHistory'] as const;

/** 判定条目类别 */
export function entryKind(prompt: { id: string }): EntryKind {
  if ((SYSTEM_PROMPT_IDS as readonly string[]).includes(prompt.id)) return 'system';
  if ((PLACEHOLDER_IDS as readonly string[]).includes(prompt.id)) return 'placeholder';
  return 'normal';
}

/** 该条目是否应显示位置字段 */
export function hasPositionField(prompt: { id: string }): boolean {
  return !(POSITIONLESS_PLACEHOLDER_IDS as readonly string[]).includes(prompt.id);
}

/* ============ 默认工作区 ============ */

export function defaultRenderTemplate(): string {
  return ['{{// 由「预设缝合助手」生成 }}', '{{// === 来自：{presetName} ===}}', '{lines}'].join('\n');
}

/** 新建一个空槽位 */
export function createEmptySlot(id: string, name = ''): StitchSlot {
  return {
    id,
    name,
    skeletonId: null,
    paramsOverride: {},
    prompts: [],
    variables: {
      agreedValue: {},
      excluded: [],
      ignoredConsolePromptIds: [],
      consoleUid: null,
      renderTemplate: defaultRenderTemplate(),
    },
    regexes: [],
  };
}

export function createEmptyWorkspace(): Workspace {
  return {
    version: 2,
    imports: [],
    slots: [],
    activeSlotId: null,
    theme: 'dark',
    ai: {
      keyword: '',
      injectionUids: [],
      selectedPresetIds: [],
      prompts: { filter: '', rewrite: '', regex: '' },
    },
  };
}
