<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue';
import { conflictUids, detectEntryConflicts } from '../core/conflict.ts';
import SplitHandle from './SplitHandle.vue';
import { useWorkspaceStore } from '../core/store.ts';
import { VARIABLE_CONSOLE_UID } from '../types.ts';

const props = defineProps<{ 选中uid: string | null }>();
const emit = defineEmits<{ 选中: [uid: string] }>();

const store = useWorkspaceStore();

/** 上半区高度占比，拖中间那根线可调 */
const 上半占比 = ref(50);

/*
 * 样式必须用 computed 返回对象，不能在模板里写 `:style="{ flex: `${上半占比} 1 0%` }"`。
 * 模板字符串里的 ref 一旦没被正确解包，生成的就是 "[object Object] 1 0%" 这种非法 CSS，
 * 整条声明被浏览器丢弃，元素退回内容高度 —— 上半区撑满、分隔线掉到最底部。
 */
const 上半样式 = computed(() => ({ flex: `${上半占比.value} 1 0%` }));
const 下半样式 = computed(() => ({ flex: `${100 - 上半占比.value} 1 0%` }));
/** 组件根元素，用于在正确的文档里查询与滚动 */
const 根元素 = ref<HTMLElement | null>(null);
const 拖拽索引 = ref<number | null>(null);
const 批量模式 = ref(false);
const 勾选 = ref<Set<string>>(new Set());



const 目标 = computed(() => store.slot.prompts);
const 冲突 = computed(() => detectEntryConflicts(目标.value));
const 冲突标记 = computed(() => conflictUids(冲突.value));
const 已改写数 = computed(() => 目标.value.filter(t => t._mode !== 'raw').length);

/** 选中某条时，上下两栏一起滚动定位 —— 这就是「上下联动」 */
watch(
  () => props.选中uid,
  async uid => {
    if (!uid) return;
    await nextTick();
    for (const 栏 of ['原文', '改写']) {
      元素文档(根元素.value)
        .querySelector(`[data-栏="${栏}"][data-uid="${CSS.escape(uid)}"]`)
        ?.scrollIntoView({
        block: 'nearest',
        behavior: 'smooth',
      });
    }
  },
);

const 色板 = ['#38bdf8', '#a78bfa', '#fb923c', '#4ade80', '#f472b6', '#facc15'];
const 颜色 = computed(() => {
  const 映射 = new Map<string, string>();
  store.workspace.imports.forEach((item, index) => 映射.set(item.id, 色板[index % 色板.length]));
  return 映射;
});

function 来源名(uid: string): string {
  const 条目 = 目标.value.find(t => t._uid === uid);
  if (!条目?._from) return '手工新建';
  return store.workspace.imports.find(i => i.id === 条目._from!.presetId)?.name ?? '来源已删除';
}

function 可拖拽(uid: string): boolean {
  return uid !== VARIABLE_CONSOLE_UID;
}

function 落位(目标索引: number) {
  if (拖拽索引.value === null || 拖拽索引.value === 目标索引) return;
  const 列表 = [...目标.value];
  const [移动项] = 列表.splice(拖拽索引.value, 1);
  if (移动项._uid === VARIABLE_CONSOLE_UID) {
    拖拽索引.value = null;
    return;
  }
  列表.splice(目标索引, 0, 移动项);
  store.slot.prompts = 列表;
  拖拽索引.value = null;
  store.save();
}

watch(批量模式, 开 => {
  if (!开) 勾选.value = new Set();
});

function 切换勾选(uid: string) {
  const 下一个 = new Set(勾选.value);
  下一个.has(uid) ? 下一个.delete(uid) : 下一个.add(uid);
  勾选.value = 下一个;
}

/** 一键清空当前缝合槽位的目标条目与正则 */
function 清空槽位() {
  const 确认 = confirm(`确定清空当前槽位的 ${目标.value.length} 条目标条目吗？正则列表也会一并清空；骨架与全局参数保留。`);
  if (!确认) return;
  store.清空当前槽位();
  toastr.success('已清空当前缝合槽位', '预设缝合助手');
}

function 全选() {
  勾选.value = 勾选.value.size > 0 ? new Set() : new Set(目标.value.map(t => t._uid));
}

function 批量移除() {
  const 数 = store.批量移除条目([...勾选.value]);
  勾选.value = new Set();
  toastr.success(`已移除 ${数} 条`, '预设缝合助手');
}

const 冲突说明 = computed(() => {
  const 映射 = new Map<string, string>();
  for (const 冲突项 of 冲突.value) {
    if (冲突项.type === 'duplicate_system') 映射.set(冲突项.uid, '与目标中已有的系统提示词重复，同步会失败');
    else if (冲突项.type === 'duplicate_placeholder') 映射.set(冲突项.uid, '与目标中已有的占位符重复，同步会失败');
    else if (冲突项.type === 'same_depth')
      for (const uid of 冲突项.uids) if (!映射.has(uid)) 映射.set(uid, `与另一条挤在同一深度 ${冲突项.depth}`);
    else if (冲突项.type === 'duplicate_name')
      for (const uid of 冲突项.uids) if (!映射.has(uid)) 映射.set(uid, `名称「${冲突项.name}」与另一条重复`);
  }
  return 映射;
});
</script>

<template>
  <div ref="根元素" class="flex flex-col flex-1 min-h-0">
    <div class="p-2 border-b border-line shrink-0 flex items-center gap-2 text-xs">
      <span>目标 {{ 目标.length }} 条</span>
      <span v-if="已改写数" class="text-accent" title="已被 AI 改写的条目数">
        <i class="fa-solid fa-wand-magic-sparkles" /> {{ 已改写数 }}
      </span>
      <span v-if="冲突.length" class="text-warn"><i class="fa-solid fa-triangle-exclamation" /> {{ 冲突.length }}</span>
      <button
        class="ml-auto px-1.5 py-0.5 rounded border border-line hover:border-danger hover:text-danger text-[11px] transition-colors disabled:opacity-35"
        :disabled="目标.length === 0"
        title="清空当前槽位的全部目标条目与正则"
        @click="清空槽位"
      >
        <i class="fa-solid fa-trash-can" /> 清空
      </button>
      <button
        class="px-1.5 py-0.5 rounded border text-[11px] transition-colors"
        :class="批量模式 ? 'border-accent text-accent bg-accent-soft/40' : 'border-line hover:border-line-strong'"
        @click="批量模式 = !批量模式"
      >
        <i class="fa-solid fa-list-check" /> 批量
      </button>
    </div>

    <div v-if="批量模式" class="px-2 py-1 border-b border-line flex items-center gap-1.5 text-[11px] shrink-0">
      <button class="px-1.5 py-0.5 rounded border border-line hover:border-accent" @click="全选">
        {{ 勾选.size ? '全不选' : '全选' }}
      </button>
      <button
        class="px-2 py-0.5 rounded border border-danger text-danger disabled:opacity-40"
        :disabled="勾选.size === 0"
        @click="批量移除"
      >
        移除 {{ 勾选.size }} 条
      </button>
    </div>

    <div v-if="目标.length === 0" class="p-3 text-xs text-muted leading-relaxed">
      从左边点选条目，或到 AI 助手用关键词抓取。
    </div>

    <template v-else>
      <!-- 上半：原条目（搬进来时的原文） -->
      <div class="min-h-0 flex flex-col" :style="上半样式">
        <div class="px-2 py-1.5 shrink-0 text-[10px] text-muted bg-surface2/45 border-b border-line/50 flex items-center gap-1.5">
          <i class="fa-solid fa-file-lines" />原条目
          <span class="ml-auto opacity-70">搬进来时的原文，不会被改写覆盖</span>
        </div>
        <div class="flex-1 min-h-0 overflow-y-auto">
          <div
            v-for="item in 目标"
            :key="'原-' + item._uid"
            :data-栏="'原文'"
            :data-uid="item._uid"
            class="px-2 py-1 border-b border-line/40 text-xs cursor-pointer transition-colors"
            :class="[
              props.选中uid === item._uid ? 'bg-accent-soft/30 border-l-2 border-l-accent' : 'hover:bg-surface2/60',
              { 'border-l-2 border-l-danger': 冲突标记.get(item._uid) === 'red' },
            ]"
            :title="冲突说明.get(item._uid) ?? ''"
            @click="emit('选中', item._uid)"
          >
            <div class="flex items-center gap-1.5">
              <input
                v-if="批量模式"
                type="checkbox"
                class="shrink-0"
                :checked="勾选.has(item._uid)"
                @click.stop="切换勾选(item._uid)"
              />
              <span
                class="w-2 h-2 rounded-full shrink-0"
                :style="{ background: item._from ? 颜色.get(item._from.presetId) : 'var(--t-muted)' }"
                :title="来源名(item._uid)"
              />
              <span class="truncate flex-1">{{ item.name }}</span>
              <i
                v-if="item._uid === VARIABLE_CONSOLE_UID"
                class="fa-solid fa-lock text-warn text-[10px] shrink-0"
              />
              <button
                class="text-muted hover:text-danger shrink-0"
                title="移除该条目"
                @click.stop="store.移除目标条目(item._uid)"
              >
                <i class="fa-solid fa-xmark" />
              </button>
            </div>
            <div class="text-[10px] text-muted truncate pl-3.5">
              {{ (item._origin || item.content || '').replace(/\s+/g, ' ').slice(0, 90) || '（空）' }}
            </div>
          </div>
        </div>
      </div>
    <SplitHandle @拖动="比例 => (上半占比 = 比例)" />

      <!-- 下半：改写后的条目 -->
      <div class="min-h-0 flex flex-col" :style="下半样式">
        <div class="px-2 py-1.5 shrink-0 text-[10px] bg-surface2/45 border-b border-line/50 flex items-center gap-1.5">
          <i class="fa-solid fa-wand-magic-sparkles text-accent" />
          <span class="text-accent">改写后</span>
          <span class="ml-auto opacity-70 text-muted">AI 生成的结果写在这里</span>
        </div>
        <div class="flex-1 min-h-0 overflow-y-auto">
          <div
            v-for="item in 目标"
            :key="'改-' + item._uid"
            :data-栏="'改写'"
            :data-uid="item._uid"
            class="px-2 py-1 border-b border-line/40 text-xs cursor-pointer transition-colors"
            :class="props.选中uid === item._uid ? 'bg-accent-soft/30 border-l-2 border-l-accent' : 'hover:bg-surface2/60'"
            @click="emit('选中', item._uid)"
          >
            <div class="flex items-center gap-1.5">
              <span class="truncate flex-1" :class="item._mode === 'raw' ? 'text-muted' : ''">{{ item.name }}</span>
              <span v-if="item._mode === 'raw'" class="text-[10px] text-muted shrink-0">未改写</span>
              <span v-else class="text-[10px] text-accent shrink-0">
                {{ item._mode === 'merged' ? '已合并' : '已润色' }}
              </span>
            </div>
            <div
              class="text-[10px] truncate pl-0"
              :class="item._mode === 'raw' ? 'text-muted opacity-60' : 'text-body'"
            >
              {{ (item.content || '').replace(/\s+/g, ' ').slice(0, 90) || '（空）' }}
            </div>
          </div>
        </div>
      </div>
    </template>
  </div>
</template>
