<script setup lang="ts">
import { computed, ref } from 'vue';
import {
  已中止错误,
  合并组,
  默认提示词,
  精判,
  聚类,
  粗筛,
  正则筛选,
  对齐改写,
  type 候选条目,
} from '../core/ai.ts';
import { deepClone } from '../core/clone.ts';
import { useWorkspaceStore } from '../core/store.ts';
import { 中止生成 } from '../core/tavern.ts';
import { VARIABLE_CONSOLE_UID, type PresetPrompt, type TargetPrompt } from '../types.ts';

const props = defineProps<{ track: 'entry' | 'variable' | 'regex' }>();

const store = useWorkspaceStore();
const 运行中 = ref(false);
const 阶段 = ref('');
const 展开设置 = ref(false);
const 展开预设 = ref(false);
const 展开注入 = ref(false);
const 展开提示词 = ref(false);
const 勾选 = ref<Set<string>>(new Set());

/** 用户点停止后置为 true，各批量流程每轮都会检查 */
const 已中止 = ref(false);
/** 上一次执行的操作，用于「重新生成」 */
const 上次操作 = ref<null | (() => Promise<void>)>(null);

const 候选 = ref<{ uid: string; 名称: string; 分数: number; 理由: string }[]>([]);
const 候选勾选 = ref<Set<string>>(new Set());
const 正则候选 = ref<{ id: string; 名称: string; 理由: string }[]>([]);

const 槽位 = computed(() => store.slot);

const 关键词 = computed({
  get: () => store.workspace.ai.keyword,
  set: (v: string) => {
    store.workspace.ai.keyword = v;
    store.save();
  },
});

const 提示词 = computed(() => store.workspace.ai.prompts);

function 改提示词(键: 'filter' | 'rewrite' | 'regex', 值: string) {
  store.workspace.ai.prompts = { ...store.workspace.ai.prompts, [键]: 值 };
  store.save();
}

function 恢复默认(键: 'filter' | 'rewrite' | 'regex') {
  改提示词(键, '');
}

/* ============ 运行控制 ============ */

/**
 * 统一包一层：负责运行态、中止标志、错误分类、「重新生成」的记录。
 * 主动停止不算失败 —— 报错会让用户以为出了问题。
 */
async function 运行(操作: () => Promise<void>, 重试: () => Promise<void>) {
  if (运行中.value) return;
  运行中.value = true;
  已中止.value = false;
  上次操作.value = 重试;
  try {
    await 操作();
  } catch (error) {
    if (error instanceof 已中止错误) {
      toastr.info('已停止', '预设缝合助手');
    } else {
      console.error(error);
      toastr.error(`执行失败：${error instanceof Error ? error.message : String(error)}`, '预设缝合助手');
    }
  } finally {
    运行中.value = false;
    阶段.value = '';
  }
}

/** 一键清空 AI 助手：候选结果在组件里，配置在 store 里，两边都要清 */
function 清空AI() {
  候选.value = [];
  候选勾选.value = new Set();
  正则候选.value = [];
  上次操作.value = null;
  阶段.value = '';
  store.清空AI配置();
  toastr.success('已清空 AI 助手', '预设缝合助手');
}

function 停止() {
  已中止.value = true;
  // 尽力而为：酒馆原生 generateRaw 用的是它自己的 AbortController，
  // stopGeneration() 中止的是另一个对象，所以正在飞行中的请求打断不了。
  // 真正的停止靠「已中止」标志在下一轮循环时生效。
  中止生成();
}

function 重新生成() {
  if (运行中.value || !上次操作.value) return;
  上次操作.value();
}

const 应中止 = () => 已中止.value;

/* ============ 搜索范围 ============ */

/** 本次参与搜索的源预设。没勾选时是全部 */
const 参与预设 = computed(() => {
  const 选中 = store.workspace.ai.selectedPresetIds;
  if (选中.length === 0) return store.workspace.imports;
  return store.workspace.imports.filter(i => 选中.includes(i.id));
});

const 是否限定预设 = computed(() => store.workspace.ai.selectedPresetIds.length > 0);

function 切换预设(id: string) {
  const 当前 = store.workspace.ai.selectedPresetIds;
  store.workspace.ai.selectedPresetIds = 当前.includes(id) ? 当前.filter(x => x !== id) : [...当前, id];
  store.save();
}

function 全选预设() {
  const 全部 = store.workspace.imports.map(i => i.id);
  store.workspace.ai.selectedPresetIds =
    store.workspace.ai.selectedPresetIds.length === 全部.length ? [] : 全部;
  store.save();
}

function 全部条目(): 候选条目[] {
  const 结果: 候选条目[] = [];
  for (const imported of 参与预设.value) {
    for (const p of store.条目(imported)) {
      结果.push({
        uid: `${imported.id}::${p.id}`,
        name: `${imported.name} · ${p.name}`,
        excerpt: (p.content ?? '').replace(/\s+/g, ' ').slice(0, 120),
        content: p.content ?? '',
      });
    }
  }
  return 结果;
}

const 注入内容 = computed(() =>
  槽位.value.prompts
    .filter(t => store.workspace.ai.injectionUids.includes(t._uid))
    .map(t => `### ${t.name}\n${t.content ?? ''}`)
    .join('\n\n'),
);

/* ============ 抓取条目 ============ */

async function 执行抓取() {
  if (!关键词.value.trim()) {
    toastr.warning('请先填写想要的效果关键词', '预设缝合助手');
    return;
  }
  const 全部 = 全部条目();
  if (全部.length === 0) {
    toastr.warning(是否限定预设.value ? '限定的预设里没有条目' : '还没有导入任何预设', '预设缝合助手');
    return;
  }

  await 运行(
    async () => {
      阶段.value = `粗筛中（共 ${全部.length} 条）…`;
      const 粗筛结果 = await 粗筛(全部, 关键词.value, 提示词.value.filter, 应中止);

      // 只对粗筛达标的条目做精判 —— 这是两级筛选省成本的关键
      const 入围 = 全部.filter(c => (粗筛结果.get(c.uid) ?? 0) >= 5).slice(0, 120);
      if (入围.length === 0) {
        toastr.info('没有找到相关条目，可以换个说法再试', '预设缝合助手');
        候选.value = [];
        return;
      }

      阶段.value = `精判中（${入围.length} 条）…`;
      const 精判结果 = await 精判(入围, 关键词.value, 提示词.value.filter, 应中止);
      const 名称表 = new Map(入围.map(c => [c.uid, c.name]));

      候选.value = 精判结果
        .filter(r => r.score >= 5)
        .map(r => ({ uid: r.uid, 名称: 名称表.get(r.uid) ?? r.uid, 分数: r.score, 理由: r.reason }))
        .sort((a, b) => b.分数 - a.分数);
      候选勾选.value = new Set(候选.value.map(c => c.uid));
      toastr.success(`找到 ${候选.value.length} 条相关条目`, '预设缝合助手');
    },
    执行抓取,
  );
}

function 收候选为条目(uid列表: string[]): { prompt: PresetPrompt; presetId: string }[] {
  const 结果: { prompt: PresetPrompt; presetId: string }[] = [];
  for (const uid of uid列表) {
    const [presetId, promptId] = uid.split('::');
    const imported = store.workspace.imports.find(i => i.id === presetId);
    if (!imported) continue;
    const prompt = store.条目(imported).find(p => p.id === promptId);
    if (prompt) 结果.push({ prompt, presetId });
  }
  return 结果;
}

function 加入勾选的候选() {
  const 数 = store.批量加入条目(收候选为条目([...候选勾选.value]));
  toastr.success(数 ? `已加入 ${数} 条` : '勾选的条目都已在目标中', '预设缝合助手');
}

function 加入候选(uid: string) {
  const 数 = store.批量加入条目(收候选为条目([uid]));
  if (!数) toastr.info('该条目已在目标中', '预设缝合助手');
}

function 切换候选勾选(uid: string) {
  const 下一个 = new Set(候选勾选.value);
  下一个.has(uid) ? 下一个.delete(uid) : 下一个.add(uid);
  候选勾选.value = 下一个;
}

/* ============ 改写（先预览，后写入） ============ */

const 术语参照 = computed(() => {
  const skeleton = store.skeleton;
  if (!skeleton) return '';
  return store
    .条目(skeleton)
    .filter(p => ['main', 'nsfw', 'jailbreak'].includes(p.id) && p.content)
    .map(p => `### ${p.name}\n${(p.content ?? '').slice(0, 2000)}`)
    .join('\n\n');
});

/** 执行改写，结果只进预览区，不动目标条目 */
async function 执行改写(模式: '对齐' | '合并') {
  const 待改 = 槽位.value.prompts.filter(t => t._uid !== VARIABLE_CONSOLE_UID);
  if (待改.length === 0) {
    toastr.warning('目标栏里还没有条目', '预设缝合助手');
    return;
  }

  await 运行(
    async () => {
      let 已写入 = 0;

      if (模式 === '对齐') {
        for (let i = 0; i < 待改.length; i++) {
          阶段.value = `对齐润色 ${i + 1}/${待改.length}（完成后写入「改写后」栏）…`;
          const 条目 = 待改[i];
          // 重新取一次最新内容：上一轮写入后数组项已替换
          const 最新 = 槽位.value.prompts.find(t => t._uid === 条目._uid);
          if (!最新) continue;
          const 新内容 = await 对齐改写(
            最新.content ?? '',
            术语参照.value,
            注入内容.value,
            提示词.value.rewrite,
            应中止,
          );
          写回条目(最新._uid, 新内容, 'aligned', 最新.name);
          已写入++;
        }
      } else {
        阶段.value = '聚类中…';
        const 分组 = await 聚类(
          待改.map(t => ({ uid: t._uid, name: t.name, content: t.content ?? '' })),
          提示词.value.rewrite,
          应中止,
        );
        const 待改表 = new Map(待改.map(t => [t._uid, t]));

        for (const [下标, 组] of 分组.entries()) {
          if (组.length <= 1) continue;
          阶段.value = `合并第 ${下标 + 1}/${分组.length} 组…`;
          const 成员 = 组.map(uid => 待改表.get(uid)).filter(Boolean) as TargetPrompt[];
          if (成员.length <= 1) continue;

          const 合并结果 = await 合并组(
            成员.map(m => ({ name: m.name, content: m.content ?? '' })),
            提示词.value.rewrite,
            应中止,
          );
          写回条目(成员[0]._uid, 合并结果, 'merged', 成员[0].name, 组);
          已写入++;
        }
      }

      toastr.success(
        已写入
          ? `已改写 ${已写入} 条，结果在中栏右侧「改写后」栏，可逐条还原为原文`
          : '没有产生任何改写结果',
        '预设缝合助手',
      );
    },
    () => 执行改写(模式),
  );
}

/** 把改写结果写回目标条目（原文保留在 _origin 里，供还原与对照） */
function 写回条目(
  uid: string,
  内容: string,
  模式: 'aligned' | 'merged',
  名称: string,
  合并成员?: string[],
) {
  const 下标 = 槽位.value.prompts.findIndex(t => t._uid === uid);
  if (下标 === -1) return;

  const 列表 = [...槽位.value.prompts];
  const 原 = 列表[下标];
  列表[下标] = {
    ...原,
    content: 内容,
    name: 名称,
    _mode: 模式,
    // _origin 只在首次改写时记录，保证「还原为原文」能回到最初搬进来的样子
    _origin: 原._origin || (原.content ?? ''),
  };

  // 合并模式下，被合并掉的其余条目要从目标里移除，避免内容重复
  槽位.value.prompts = 合并成员 ? 列表.filter(t => t._uid === uid || !合并成员.includes(t._uid)) : 列表;
  store.save();
}

/* ============ 正则筛选 ============ */

async function 执行正则筛选() {
  if (!关键词.value.trim()) {
    toastr.warning('请先填写需求', '预设缝合助手');
    return;
  }
  const 参与集 = new Set(参与预设.value.map(i => i.id));
  const 全部 = store.正则来源.filter(e => 参与集.has(e.presetId));
  if (全部.length === 0) {
    toastr.warning('限定范围内没有正则', '预设缝合助手');
    return;
  }

  await 运行(
    async () => {
      阶段.value = `筛选中（共 ${全部.length} 条）…`;
      const 结果 = await 正则筛选(
        全部.map(e => ({
          id: e.regex.id,
          name: `${e.presetName} · ${e.regex.script_name}`,
          find: e.regex.find_regex,
        })),
        关键词.value,
        提示词.value.regex,
        应中止,
      );
      const 名称表 = new Map(全部.map(e => [e.regex.id, e.regex.script_name]));
      正则候选.value = 结果.map(r => ({ id: r.id, 名称: 名称表.get(r.id) ?? r.id, 理由: r.理由 }));
      toastr.success(`筛出 ${正则候选.value.length} 条相关正则`, '预设缝合助手');
    },
    执行正则筛选,
  );
}

function 加入正则(id: string) {
  const entry = store.正则来源.find(e => e.regex.id === id);
  if (!entry) return;
  if (槽位.value.regexes.some(r => r.id === id)) {
    toastr.info('该正则已在目标中', '预设缝合助手');
    return;
  }
  store.批量加入正则([deepClone(entry.regex)]);
}
</script>

<template>
  <div class="flex-1 min-h-0 overflow-y-auto p-2.5 space-y-2.5">
    <div>
      <div class="flex items-center gap-2">
        <span class="text-xs text-muted flex-1">
          {{ props.track === 'regex' ? '想要的正则效果' : '想要的效果关键词' }}
        </span>
        <button
          class="px-1.5 py-0.5 rounded border border-line hover:border-danger hover:text-danger text-[10px] transition-colors"
          title="清空 AI 助手：关键词、候选结果、注入条目、来源限定、自定义提示词"
          @click="清空AI"
        >
          <i class="fa-solid fa-trash-can" /> 清空
        </button>
      </div>
      <textarea
        v-model="关键词"
        rows="3"
        class="w-full mt-1 text-xs"
        :placeholder="
          props.track === 'regex'
            ? '例如：清理思维链、去掉 AI 免责声明'
            : '例如：加强角色扮演的代入感、让旁白更克制'
        "
      />
    </div>

    <!-- 运行状态 / 控制 -->
    <div v-if="运行中" class="space-y-1 text-xs">
      <div class="flex items-center gap-2">
        <i class="fa-solid fa-spinner fa-spin" :class="已中止 ? 'text-warn' : 'text-accent'" />
        <span class="flex-1" :class="已中止 ? 'text-warn' : 'text-accent'">
          {{ 已中止 ? '正在停止…' : 阶段 || '处理中…' }}
        </span>
        <button
          v-if="!已中止"
          class="px-2 py-0.5 rounded border border-danger text-danger hover:bg-danger/10"
          title="停止批量处理"
          @click="停止"
        >
          <i class="fa-solid fa-stop" /> 停止
        </button>
      </div>
      <p v-if="已中止" class="text-[10px] text-muted leading-relaxed">
        已经发出、正在生成的那一条无法中途打断（酒馆原生 generateRaw 的限制），
        它结束后就会停下，已完成的部分会保留。
      </p>
    </div>
    <button
      v-else-if="上次操作"
      class="w-full px-3 py-1 rounded-md border border-line hover:border-accent text-xs"
      title="用同样的参数再跑一次"
      @click="重新生成"
    >
      <i class="fa-solid fa-rotate-right mr-1" />重新生成
    </button>

    <!-- 高级设置 -->
    <details class="border border-line rounded-md">
      <summary class="px-2 py-1 cursor-pointer select-none text-xs text-muted" @click="展开设置 = !展开设置">
        高级设置
      </summary>
      <div class="p-2 space-y-2 border-t border-line">
        <!-- 限定搜索范围 -->
        <div>
          <button
            class="w-full text-left px-2 py-1 rounded-md bg-surface2 hover:bg-line text-xs flex items-center gap-1"
            @click="展开预设 = !展开预设"
          >
            <span class="flex-1">缝合来源预设</span>
            <span :class="是否限定预设 ? 'text-accent' : 'text-muted'">
              {{ 是否限定预设 ? `已选 ${store.workspace.ai.selectedPresetIds.length}` : '全部' }}
            </span>
          </button>
          <div v-if="展开预设" class="mt-1 border border-line rounded-md max-h-40 overflow-y-auto">
            <div class="flex items-center gap-2 px-2 py-1 border-b border-line text-[10px] text-muted">
              <span class="flex-1">不勾 = 在所有导入的预设里找</span>
              <button class="hover:text-accent" @click="全选预设">
                {{
                  store.workspace.ai.selectedPresetIds.length === store.workspace.imports.length
                    ? '全不选'
                    : '全选'
                }}
              </button>
            </div>
            <label
              v-for="item in store.workspace.imports"
              :key="item.id"
              class="flex items-center gap-1.5 px-2 py-0.5 text-xs hover:bg-surface2/60 cursor-pointer"
            >
              <input
                type="checkbox"
                :checked="store.workspace.ai.selectedPresetIds.includes(item.id)"
                @change="切换预设(item.id)"
              />
              <span class="truncate flex-1">{{ item.name }}</span>
              <span class="text-[10px] text-muted">{{ store.条目(item).length }}</span>
            </label>
            <div v-if="store.workspace.imports.length === 0" class="p-2 text-xs text-muted">
              还没有导入任何预设
            </div>
          </div>
        </div>

        <!-- 注入条目 -->
        <div>
          <button
            class="w-full text-left px-2 py-1 rounded-md bg-surface2 hover:bg-line text-xs"
            @click="展开注入 = !展开注入"
          >
            注入条目（作为 AI 的固定参照）：已选 {{ store.workspace.ai.injectionUids.length }} 条
          </button>
          <div v-if="展开注入" class="mt-1 max-h-40 overflow-y-auto border border-line rounded-md">
            <label
              v-for="item in 槽位.prompts"
              :key="item._uid"
              class="flex items-center gap-1.5 px-2 py-0.5 text-xs hover:bg-surface2/60 cursor-pointer"
            >
              <input
                type="checkbox"
                :checked="store.workspace.ai.injectionUids.includes(item._uid)"
                @change="
                  store.workspace.ai.injectionUids = store.workspace.ai.injectionUids.includes(item._uid)
                    ? store.workspace.ai.injectionUids.filter(u => u !== item._uid)
                    : [...store.workspace.ai.injectionUids, item._uid];
                  store.save();
                "
              />
              <span class="truncate">{{ item.name }}</span>
            </label>
            <div v-if="槽位.prompts.length === 0" class="p-2 text-xs text-muted">目标栏还没有条目</div>
          </div>
        </div>

        <!-- 自定义提示词 -->
        <div>
          <button
            class="w-full text-left px-2 py-1 rounded-md bg-surface2 hover:bg-line text-xs"
            @click="展开提示词 = !展开提示词"
          >
            系统提示词（留空用内置默认）
          </button>
          <div v-if="展开提示词" class="mt-1 space-y-2">
            <div
              v-for="项 in [
                { 键: 'filter' as const, 名: '抓取 / 筛选' },
                { 键: 'rewrite' as const, 名: '改写 / 聚类 / 合并' },
                { 键: 'regex' as const, 名: '正则筛选' },
              ]"
              :key="项.键"
            >
              <div class="flex items-center gap-2">
                <span class="text-[11px] text-muted flex-1">{{ 项.名 }}</span>
                <button class="text-[10px] text-muted hover:text-accent" @click="恢复默认(项.键)">恢复默认</button>
              </div>
              <textarea
                :value="提示词[项.键]"
                rows="3"
                class="w-full mt-0.5 text-[11px]"
                :placeholder="默认提示词[项.键]"
                @input="改提示词(项.键, ($event.target as HTMLTextAreaElement).value)"
              />
            </div>
          </div>
        </div>
      </div>
    </details>

    <!-- ============ 条目轨 ============ -->
    <template v-if="props.track !== 'regex'">
      <button
        class="w-full px-3 py-1.5 rounded-md bg-accent text-accent-text font-medium text-xs disabled:opacity-50"
        :disabled="运行中"
        @click="执行抓取"
      >
        <i class="fa-solid fa-magnifying-glass mr-1" />抓取相关条目
      </button>

      <div v-if="候选.length" class="space-y-1">
        <div class="flex items-center gap-2 text-[11px] text-muted">
          <span class="flex-1">候选 {{ 候选.length }} 条</span>
          <button
            class="hover:text-accent"
            @click="候选勾选 = 候选勾选.size ? new Set() : new Set(候选.map(c => c.uid))"
          >
            {{ 候选勾选.size ? '全不选' : '全选' }}
          </button>
        </div>
        <div v-for="item in 候选" :key="item.uid" class="border border-line rounded-md p-1.5 text-[11px] flex gap-1.5">
          <input
            type="checkbox"
            class="shrink-0 mt-0.5"
            :checked="候选勾选.has(item.uid)"
            @change="切换候选勾选(item.uid)"
          />
          <div class="flex-1 min-w-0">
            <div class="truncate">{{ item.名称 }}</div>
            <div class="text-muted"><span class="text-accent">{{ item.分数 }}分</span> · {{ item.理由 }}</div>
          </div>
          <button class="shrink-0 text-accent hover:underline self-start" @click="加入候选(item.uid)">加入</button>
        </div>
        <button
          class="w-full px-3 py-1 rounded-md border border-accent text-accent text-xs disabled:opacity-40"
          :disabled="候选勾选.size === 0"
          @click="加入勾选的候选"
        >
          加入勾选的 {{ 候选勾选.size }} 条
        </button>
      </div>

      <!-- 改写 -->
      <div class="border-t border-line pt-2 space-y-1.5">
        <div class="text-[11px] text-muted">改写当前槽位的目标条目（先生成预览）</div>
        <div class="flex gap-1.5">
          <button
            class="flex-1 px-2 py-1 rounded-md border border-line hover:border-accent text-xs disabled:opacity-50"
            :disabled="运行中"
            @click="执行改写('对齐')"
          >
            <i class="fa-solid fa-wand-magic-sparkles mr-1" />对齐润色
          </button>
          <button
            class="flex-1 px-2 py-1 rounded-md border border-line hover:border-accent text-xs disabled:opacity-50"
            :disabled="运行中"
            @click="执行改写('合并')"
          >
            <i class="fa-solid fa-layer-group mr-1" />合并同主题
          </button>
        </div>
      </div>

    </template>

    <!-- ============ 正则轨 ============ -->
    <template v-else>
      <button
        class="w-full px-3 py-1.5 rounded-md bg-accent text-accent-text font-medium text-xs disabled:opacity-50"
        :disabled="运行中"
        @click="执行正则筛选"
      >
        <i class="fa-solid fa-magnifying-glass mr-1" />筛选相关正则
      </button>

      <div v-if="正则候选.length" class="space-y-1">
        <div class="text-[11px] text-muted">候选 {{ 正则候选.length }} 条</div>
        <div
          v-for="item in 正则候选"
          :key="item.id"
          class="border border-line rounded-md p-1.5 text-[11px] flex gap-1.5"
        >
          <div class="flex-1 min-w-0">
            <div class="truncate">{{ item.名称 }}</div>
            <div class="text-muted">{{ item.理由 }}</div>
          </div>
          <button class="shrink-0 text-accent hover:underline self-start" @click="加入正则(item.id)">加入</button>
        </div>
      </div>

      <p class="text-[10px] text-muted leading-relaxed">
        正则之间的冲突（重复、高度相似、作用域重叠）会在中栏右侧标黄提示。
      </p>
    </template>
  </div>
</template>
