import { defineStore } from 'pinia';
import { deepClone } from './clone.ts';
import { normalizeLegacyRegex } from './regex.ts';
import { getPreset, getPresetNames, 写入扩展数据, 读取扩展数据 } from './tavern.ts';
import {
  createEmptySlot,
  createEmptyWorkspace,
  type ImportedPreset,
  type LegacyRegexScript,
  type Preset,
  type PresetPrompt,
  type RegexSourceEntry,
  type StitchSlot,
  type TargetPrompt,
  type TavernRegex,
  type Workspace,
} from '../types.ts';

const STORAGE_KEY = 'workspace';
const DEBOUNCE_MS = 1000;
const SIZE_LIMIT = 4 * 1024 * 1024;

/** 生成唯一 id。优先用浏览器的 crypto.randomUUID，退回随机串 */
function 生成Id(): string {
  return crypto?.randomUUID?.() ?? `id-${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

/**
 * 把旧版（v1）工作区迁移到 v2。
 * v1 是「一个工作区一份缝合结果」，v2 是「多个槽位」。迁移方式是把原来那份结果装进第一个槽位。
 */
function 迁移旧工作区(raw: Record<string, any>): Workspace {
  const 基础 = createEmptyWorkspace();
  const 槽位 = createEmptySlot(生成Id(), raw.targetName ?? '');
  槽位.skeletonId = raw.skeletonId ?? null;
  槽位.paramsOverride = {};
  槽位.prompts = Array.isArray(raw.targetPrompts) ? raw.targetPrompts : [];
  槽位.regexes = Array.isArray(raw.regexes?.target) ? raw.regexes.target : [];
  槽位.variables = {
    agreedValue: raw.variables?.agreedValue ?? {},
    excluded: [],
    ignoredConsolePromptIds: raw.variables?.ignoredConsolePromptIds ?? [],
    consoleUid: raw.variables?.consoleUid ?? null,
    renderTemplate: raw.variables?.renderTemplate ?? createEmptySlot(生成Id()).variables.renderTemplate,
  };

  const 旧提示词 = raw.ai?.prompts ?? {};
  return {
    ...基础,
    imports: Array.isArray(raw.imports) ? raw.imports : [],
    slots: [槽位],
    activeSlotId: 槽位.id,
    ai: {
      keyword: raw.ai?.keyword ?? '',
      injectionUids: raw.ai?.injectionUids ?? [],
      selectedPresetIds: raw.ai?.selectedPresetIds ?? [],
      // v1 的 mine/merge 合并语义已拆成 filter/rewrite，旧值按最接近的含义带过去
      prompts: { filter: 旧提示词.mine ?? '', rewrite: 旧提示词.merge ?? '', regex: 旧提示词.regex ?? '' },
    },
  };
}

/** 从扩展设置读取工作区, 失败或版本不符则回退 */
function loadWorkspace(): Workspace {
  try {
    const raw = 读取扩展数据()?.[STORAGE_KEY];
    if (!raw || !Array.isArray(raw.imports)) return createEmptyWorkspace();

    if (raw.version === 1) {
      console.info('[预设缝合助手] 检测到旧版工作区，已自动迁移到多槽位结构');
      return 迁移旧工作区(raw);
    }
    if (raw.version !== 2) return createEmptyWorkspace();

    const 基础 = createEmptyWorkspace();
    return {
      ...基础,
      ...raw,
      imports: raw.imports,
      slots: (Array.isArray(raw.slots) ? raw.slots : []).map((s: Record<string, any>) => ({
        ...createEmptySlot(s.id ?? 生成Id(), s.name ?? ''),
        ...s,
        paramsOverride: s.paramsOverride ?? {},
        prompts: Array.isArray(s.prompts) ? s.prompts : [],
        regexes: Array.isArray(s.regexes) ? s.regexes : [],
      })),
      ai: {
        ...基础.ai,
        ...(raw.ai ?? {}),
        prompts: { ...基础.ai.prompts, ...(raw.ai?.prompts ?? {}) },
      },
    } as Workspace;
  } catch (error) {
    console.error('[预设缝合助手] 工作区读取失败, 使用空工作区', error);
    return createEmptyWorkspace();
  }
}

/** 把酒馆原生格式的正则统一成归一化格式 */
function normalizePresetRegexes(preset: Preset): TavernRegex[] {
  const scripts = preset.extensions?.regex_scripts;
  if (!Array.isArray(scripts)) return [];
  return scripts.map(raw =>
    raw && typeof raw === 'object' && 'scriptName' in raw
      ? normalizeLegacyRegex(raw as unknown as LegacyRegexScript)
      : (raw as TavernRegex),
  );
}

export const useWorkspaceStore = defineStore('预设缝合助手', {
  state: () => ({
    workspace: loadWorkspace() as Workspace,
    degradedReason: '',
    saving: false,
  }),

  getters: {
    /** 当前正在编辑的槽位。没有槽位时自动新建一个，保证界面永远有可操作的目标 */
    slot(state): StitchSlot {
      const 找到 = state.workspace.slots.find(s => s.id === state.workspace.activeSlotId);
      return 找到 ?? state.workspace.slots[0] ?? createEmptySlot('placeholder');
    },

    /** 可导入的预设名 (已导入的不再列出) */
    availablePresetNames(state): string[] {
      const imported = new Set(state.workspace.imports.map(i => i.name));
      return getPresetNames().filter(name => !imported.has(name));
    },

    skeleton(state): ImportedPreset | null {
      const 槽位 = this.slot;
      return state.workspace.imports.find(i => i.id === 槽位.skeletonId) ?? null;
    },

    /** 已在当前槽位目标栏里的条目 uid 集合 */
    targetUidSet(): Set<string> {
      return new Set(this.slot.prompts.map(t => t._uid));
    },

    /** 所有导入预设的正则（归一化后），带来源信息 */
    正则来源(state): RegexSourceEntry[] {
      const result: RegexSourceEntry[] = [];
      for (const imported of state.workspace.imports) {
        for (const regex of normalizePresetRegexes(imported.raw)) {
          result.push({ presetId: imported.id, presetName: imported.name, regex });
        }
      }
      return result;
    },
  },

  actions: {
    /* ============ 槽位管理 ============ */

    新建槽位(name = ''): StitchSlot {
      const 槽位 = createEmptySlot(生成Id(), name);
      // 新槽位默认沿用当前槽位的骨架，省去重选
      槽位.skeletonId = this.slot?.skeletonId ?? this.workspace.imports[0]?.id ?? null;
      this.workspace.slots.push(槽位);
      this.workspace.activeSlotId = 槽位.id;
      this.save();
      return 槽位;
    },

    /** 复制当前槽位，便于在一个成品基础上改出变体 */
    复制槽位(id: string): StitchSlot | null {
      const 源 = this.workspace.slots.find(s => s.id === id);
      if (!源) return null;
      const 副本 = deepClone(源);
      副本.id = 生成Id();
      副本.name = `${源.name || '未命名'} 副本`;
      // 目标条目的 uid 也要重新生成，否则两个槽位会共享同一批 uid
      副本.prompts = 副本.prompts.map(p => ({ ...p, _uid: `${副本.id}::${p.id}::${Math.random().toString(36).slice(2, 7)}` }));
      副本.variables.consoleUid = 副本.prompts.find(p => p.id === 'var-console')?._uid ?? null;
      this.workspace.slots.push(副本);
      this.workspace.activeSlotId = 副本.id;
      this.save();
      return 副本;
    },

    删除槽位(id: string) {
      if (this.workspace.slots.length <= 1) {
        toastr.warning('至少要保留一个缝合槽位', '预设缝合助手');
        return;
      }
      this.workspace.slots = this.workspace.slots.filter(s => s.id !== id);
      if (this.workspace.activeSlotId === id) {
        this.workspace.activeSlotId = this.workspace.slots[0].id;
      }
      this.save();
    },

    切换槽位(id: string) {
      this.workspace.activeSlotId = id;
      this.save();
    },

    重命名槽位(id: string, name: string) {
      const 槽位 = this.workspace.slots.find(s => s.id === id);
      if (槽位) 槽位.name = name;
      this.save();
    },

    /* ============ 源预设导入 ============ */

    /** 取某个导入预设的全部条目（含下拉框里未使用的） */
    条目(imported: ImportedPreset): PresetPrompt[] {
      return [...(imported.raw.prompts ?? []), ...(imported.raw.prompts_unused ?? [])];
    },

    importFromTavern(name: string): ImportedPreset | null {
      let snapshot: Preset;
      try {
        snapshot = getPreset(name);
      } catch (error) {
        toastr.error(
          `读取预设「${name}」失败：${error instanceof Error ? error.message : String(error)}`,
          '预设缝合助手',
        );
        return null;
      }
      return this.推动导入(name, 'tavern', snapshot);
    },

    importFromJson(name: string, json: string): ImportedPreset | null {
      let parsed: Preset;
      try {
        parsed = JSON.parse(json) as Preset;
      } catch (error) {
        toastr.error(`JSON 解析失败：${error instanceof Error ? error.message : String(error)}`, '预设缝合助手');
        return null;
      }
      if (!Array.isArray(parsed?.prompts)) {
        toastr.error('这不是一个酒馆预设文件（缺少 prompts 字段）', '预设缝合助手');
        return null;
      }
      return this.推动导入(name, 'file', parsed);
    },

    推动导入(name: string, source: 'tavern' | 'file', raw: Preset): ImportedPreset {
      const imported: ImportedPreset = {
        id: 生成Id(),
        name,
        source,
        raw: deepClone(raw),
        importedAt: Date.now(),
      };
      this.workspace.imports.push(imported);
      // 所有槽位都没选骨架时，把新导入的设为其骨架
      for (const 槽位 of this.workspace.slots) {
        if (!槽位.skeletonId) 槽位.skeletonId = imported.id;
      }
      this.save();
      return imported;
    },

    /**
     * 重新从源预设拉取快照。
     * 做成显式操作而非自动同步: 自动同步会让缝合中途的结果漂移,
     * 用户分不清「这个变化是我改的还是源预设改的」。
     */
    refreshSnapshot(id: string): boolean {
      const imported = this.workspace.imports.find(i => i.id === id);
      if (!imported) return false;
      if (imported.source !== 'tavern') {
        toastr.warning('文件导入的预设无法刷新快照，请重新导入', '预设缝合助手');
        return false;
      }
      try {
        imported.raw = getPreset(imported.name);
      } catch (error) {
        toastr.error(`刷新失败：${error instanceof Error ? error.message : String(error)}`, '预设缝合助手');
        return false;
      }
      imported.importedAt = Date.now();
      this.save();
      return true;
    },

    removeImport(id: string) {
      this.workspace.imports = this.workspace.imports.filter(i => i.id !== id);
      for (const 槽位 of this.workspace.slots) {
        // 该预设贡献的目标条目一并移除，避免留下指向已删预设的悬空来源
        槽位.prompts = 槽位.prompts.filter(t => t._from?.presetId !== id);
        if (槽位.skeletonId === id) 槽位.skeletonId = this.workspace.imports[0]?.id ?? null;
      }
      this.save();
    },

    setSkeleton(id: string | null) {
      this.slot.skeletonId = id;
      this.save();
    },

    /* ============ 目标条目 ============ */

    /** 把源条目加入/移出目标栏。已存在则移除，实现点选切换 */
    切换目标条目(prompt: PresetPrompt, presetId: string) {
      const uid = `${presetId}::${prompt.id}`;
      const 槽位 = this.slot;
      const exists = 槽位.prompts.some(t => t._uid === uid);
      if (exists) {
        槽位.prompts = 槽位.prompts.filter(t => t._uid !== uid);
      } else {
        const target: TargetPrompt = {
          ...deepClone(prompt),
          _uid: uid,
          _from: { presetId, promptId: prompt.id },
          _origin: prompt.content ?? '',
          _mode: 'raw',
        };
        槽位.prompts.push(target);
      }
      this.save();
    },

    批量加入条目(条目表: { prompt: PresetPrompt; presetId: string }[]): number {
      const 槽位 = this.slot;
      let 加入数 = 0;
      for (const { prompt, presetId } of 条目表) {
        const uid = `${presetId}::${prompt.id}`;
        if (槽位.prompts.some(t => t._uid === uid)) continue;
        槽位.prompts.push({
          ...deepClone(prompt),
          _uid: uid,
          _from: { presetId, promptId: prompt.id },
          _origin: prompt.content ?? '',
          _mode: 'raw',
        });
        加入数++;
      }
      this.save();
      return 加入数;
    },

    批量移除条目(uids: string[]): number {
      const 目标集 = new Set(uids);
      const 槽位 = this.slot;
      const 前 = 槽位.prompts.length;
      槽位.prompts = 槽位.prompts.filter(t => !目标集.has(t._uid));
      this.save();
      return 前 - 槽位.prompts.length;
    },

    移除目标条目(uid: string) {
      this.slot.prompts = this.slot.prompts.filter(t => t._uid !== uid);
      this.save();
    },

    /* ============ 正则 ============ */

    切换目标正则(regex: TavernRegex) {
      const 槽位 = this.slot;
      const exists = 槽位.regexes.some(r => r.id === regex.id);
      槽位.regexes = exists
        ? 槽位.regexes.filter(r => r.id !== regex.id)
        : [...槽位.regexes, deepClone(regex)];
      this.save();
    },

    批量加入正则(正则表: TavernRegex[]): number {
      const 槽位 = this.slot;
      let 加入数 = 0;
      for (const regex of 正则表) {
        if (槽位.regexes.some(r => r.id === regex.id)) continue;
        槽位.regexes.push(deepClone(regex));
        加入数++;
      }
      this.save();
      return 加入数;
    },

    移动正则(from: number, to: number) {
      const 槽位 = this.slot;
      if (from === to || from < 0 || to < 0 || from >= 槽位.regexes.length) return;
      const 副本 = [...槽位.regexes];
      const [移动项] = 副本.splice(from, 1);
      副本.splice(to, 0, 移动项);
      槽位.regexes = 副本;
      this.save();
    },

    移除正则(id: string) {
      this.slot.regexes = this.slot.regexes.filter(r => r.id !== id);
      this.save();
    },

    /* ============ 一键清空 ============ */

    /**
     * 只留一个空槽位，其余全部重置（主题保留）。
     * 这是「核弹级」操作，界面上必须二次确认。
     */
    清空全部() {
      const 主题 = this.workspace.theme;
      const 新槽位 = createEmptySlot(生成Id());
      this.workspace = { ...createEmptyWorkspace(), theme: 主题, slots: [新槽位], activeSlotId: 新槽位.id };
      this.persistNow();
    },

    /** 清空 AI 助手的输入与配置（候选列表由组件自己清） */
    清空AI配置() {
      this.workspace.ai = {
        keyword: '',
        injectionUids: [],
        selectedPresetIds: [],
        prompts: { filter: '', rewrite: '', regex: '' },
      };
      this.save();
    },

    /**
     * 清空全部已导入的源预设。
     * 因为目标条目都引用着来源预设，一并清掉，否则会留下悬空来源。
     */
    清空已导入预设() {
      this.workspace.imports = [];
      for (const 槽位 of this.workspace.slots) {
        槽位.prompts = [];
        槽位.skeletonId = null;
      }
      this.workspace.ai.injectionUids = [];
      this.workspace.ai.selectedPresetIds = [];
      this.save();
    },

    /** 清空当前缝合槽位的目标条目与正则，保留骨架与参数设置 */
    清空当前槽位() {
      const 槽位 = this.slot;
      槽位.prompts = [];
      槽位.regexes = [];
      槽位.variables.agreedValue = {};
      槽位.variables.excluded = [];
      槽位.variables.consoleUid = null;
      this.save();
    },

    /* ============ 主题 ============ */

    切换主题() {
      this.workspace.theme = this.workspace.theme === 'dark' ? 'light' : 'dark';
      this.save();
    },

    /* ============ 持久化 ============ */

    save() {
      if (this.saving) return;
      this.saving = true;
      setTimeout(() => {
        this.saving = false;
        this.persistNow();
      }, DEBOUNCE_MS);
    },

    persistNow() {
      try {
        const serialized = JSON.stringify(this.workspace);
        if (serialized.length > SIZE_LIMIT) {
          // 超限降级: 丢掉源快照, 只保留缝合结果与选择状态
          const light: Workspace = {
            ...this.workspace,
            imports: this.workspace.imports.map(i => ({
              ...i,
              raw: { settings: {}, prompts: [], prompts_unused: [], extensions: {} },
            })),
          };
          写入扩展数据({ [STORAGE_KEY]: light });
          this.degradedReason = `工作区超过 ${Math.round(SIZE_LIMIT / 1024 / 1024)}MB，本次只保存了缝合结果，源预设快照未保存（重开面板后需重新导入）`;
          toastr.warning(this.degradedReason, '预设缝合助手');
          return;
        }
        写入扩展数据({ [STORAGE_KEY]: this.workspace });
      } catch (error) {
        console.error('[预设缝合助手] 工作区保存失败', error);
        toastr.error('工作区保存失败，详见控制台', '预设缝合助手');
      }
    },
  },
});
