<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { deepClone } from '../core/clone.ts';
import SplitHandle from './SplitHandle.vue';
import { useWorkspaceStore } from '../core/store.ts';
import { VARIABLE_CONSOLE_UID, entryKind, hasPositionField, type TargetPrompt } from '../types.ts';

const props = defineProps<{ uid: string | null }>();

const store = useWorkspaceStore();

/** 上半区高度占比，拖中间那根线可调 */
const 上半占比 = ref(34);

/*
 * 样式必须用 computed 返回对象，不能在模板里写 `:style="{ flex: `${上半占比} 1 0%` }"`。
 * 模板字符串里的 ref 一旦没被正确解包，生成的就是 "[object Object] 1 0%" 这种非法 CSS，
 * 整条声明被浏览器丢弃，元素退回内容高度 —— 上半区撑满、分隔线掉到最底部。
 */
const 上半样式 = computed(() => ({ flex: `${上半占比.value} 1 0%` }));
const 下半样式 = computed(() => ({ flex: `${100 - 上半占比.value} 1 0%` }));
const 高级展开 = ref(false);



const 原文条目 = computed(() => store.slot.prompts.find(t => t._uid === props.uid) ?? null);

/** 局部编辑缓冲：改完点保存才写回 */
const 草稿 = ref<TargetPrompt | null>(null);
watch(
  原文条目,
  value => {
    草稿.value = value ? deepClone(value) : null;
  },
  { immediate: true },
);

const 类别 = computed(() => (草稿.value ? entryKind(草稿.value) : 'normal'));
const 显示位置 = computed(() => (草稿.value ? hasPositionField(草稿.value) : false));
const 是相对位置 = computed(() => 草稿.value?.position?.type !== 'in_chat');
const 原文内容 = computed(() => 原文条目.value?._origin ?? '');
const 已改写 = computed(() => (原文条目.value?._mode ?? 'raw') !== 'raw');
const 有差异 = computed(() => !!草稿.value && 草稿.value.content !== 原文内容.value);
const 是变量控制台 = computed(() => 草稿.value?._uid === VARIABLE_CONSOLE_UID);

function 保存() {
  if (!草稿.value) return;
  const 列表 = store.slot.prompts;
  const 下标 = 列表.findIndex(t => t._uid === 草稿.value!._uid);
  if (下标 === -1) return;
  // _origin 保持不动 —— 它记录搬运/改写前的原文
  列表[下标] = { ...草稿.value, _origin: 列表[下标]._origin };
  store.save();
  toastr.success('已保存', '预设缝合助手');
}

function 还原原文() {
  if (!草稿.value) return;
  草稿.value.content = 原文内容.value;
  草稿.value._mode = 'raw';
  保存();
}

function 切换位置类型(相对: boolean) {
  if (!草稿.value) return;
  草稿.value.position = 相对 ? { type: 'relative' } : { type: 'in_chat', depth: 4, order: 100 };
}
</script>

<template>
  <div v-if="!草稿" class="p-4 text-xs text-muted leading-relaxed">
    在中栏点选一个目标条目开始编辑。
  </div>

  <div v-else class="flex-1 min-h-0 flex flex-col">
    <!-- 头部信息 -->
    <div class="px-2.5 py-1.5 shrink-0 flex items-center gap-2 text-xs border-b border-line flex-wrap">
      <span class="px-1.5 py-0.5 rounded bg-surface2 text-muted">
        {{ 类别 === 'system' ? '系统提示词' : 类别 === 'placeholder' ? '占位符' : '普通条目' }}
      </span>
      <span v-if="已改写" class="text-accent">
        <i class="fa-solid fa-wand-magic-sparkles" /> {{ 草稿._mode === 'merged' ? '由多条合并' : 'AI 对齐润色' }}
      </span>
      <span v-if="是变量控制台" class="text-warn"><i class="fa-solid fa-lock" /> 锁定首位</span>
    </div>

    <!-- 上半：原文（只读） -->
    <div class="min-h-0 flex flex-col" :style="上半样式">
      <div class="px-2.5 py-1.5 shrink-0 text-[10px] bg-surface2/45 text-muted border-b border-line/50 flex items-center gap-1.5">
        <i class="fa-solid fa-file-lines" />原文
        <span class="ml-auto opacity-70">搬进来时的内容，只读</span>
      </div>
      <pre
        class="flex-1 min-h-0 overflow-auto m-2 p-2 rounded-md bg-surface2/50 text-[11px] leading-relaxed whitespace-pre-wrap font-mono"
      >{{ 原文内容 || '（无原文，例如手工新建的条目）' }}</pre>
    </div>
    <SplitHandle @拖动="比例 => (上半占比 = 比例)" />

    <!-- 下半：改写后（可编辑） -->
    <div class="min-h-0 flex flex-col" :style="下半样式">
      <div class="px-2.5 py-1.5 shrink-0 text-[10px] bg-surface2/45 border-b border-line/50 flex items-center gap-1.5">
        <i class="fa-solid fa-pen-to-square text-accent" />
        <span class="text-accent">改写后</span>
        <span v-if="有差异" class="text-warn ml-auto">与原文不同</span>
        <span v-else class="text-muted ml-auto">与原文一致</span>
      </div>

      <div class="flex-1 min-h-0 overflow-y-auto p-2 space-y-2 text-xs">
        <label class="block">
          <span class="text-muted">名称</span>
          <input v-model="草稿.name" class="w-full mt-0.5" />
        </label>

        <label class="block">
          <span class="text-muted">内容</span>
          <textarea v-model="草稿.content" rows="10" class="w-full mt-0.5 text-[11px]" />
        </label>

        <div class="flex items-center gap-4">
          <label class="flex items-center gap-1.5 cursor-pointer">
            <input v-model="草稿.enabled" type="checkbox" />启用
          </label>
          <label class="flex items-center gap-1.5">
            <span class="text-muted">角色</span>
            <select v-model="草稿.role">
              <option value="system">system</option>
              <option value="user">user</option>
              <option value="assistant">assistant</option>
            </select>
          </label>
        </div>

        <details v-if="显示位置" class="border border-line rounded-md">
          <summary class="px-2 py-1 cursor-pointer select-none text-muted" @click="高级展开 = !高级展开">
            高级 · 插入方式
          </summary>
          <div class="p-2 space-y-2 border-t border-line">
            <label class="flex items-center gap-2 cursor-pointer">
              <input type="radio" :checked="是相对位置" @change="切换位置类型(true)" /> 相对位置
            </label>
            <label class="flex items-center gap-2 cursor-pointer">
              <input type="radio" :checked="!是相对位置" @change="切换位置类型(false)" /> 插入到聊天深度
            </label>
            <div v-if="!是相对位置" class="flex items-center gap-3 pl-5">
              <label class="flex items-center gap-1">
                深度
                <input
                  :value="(草稿.position as any)?.depth"
                  type="number"
                  min="0"
                  class="w-16"
                  @input="(草稿.position as any).depth = Number(($event.target as HTMLInputElement).value)"
                />
              </label>
              <label class="flex items-center gap-1">
                顺序
                <input
                  :value="(草稿.position as any)?.order"
                  type="number"
                  class="w-20"
                  @input="(草稿.position as any).order = Number(($event.target as HTMLInputElement).value)"
                />
              </label>
            </div>
          </div>
        </details>

        <div class="flex gap-2 pt-0.5">
          <button class="px-3 py-1 rounded-md bg-accent text-accent-text font-medium" @click="保存">保存</button>
          <button
            class="px-3 py-1 rounded-md border border-line hover:border-line-strong disabled:opacity-40"
            :disabled="!原文内容"
            title="把内容还原为搬进来时的原文"
            @click="还原原文"
          >
            还原为原文
          </button>
        </div>
      </div>
    </div>
  </div>
</template>
