<script setup lang="ts">
import { computed, ref } from 'vue';
import { useWorkspaceStore } from '../core/store.ts';

const emit = defineEmits<{ 选中预设: [id: string] }>();
const 批量模式 = defineModel<boolean>('批量模式', { default: false });

const store = useWorkspaceStore();
const 展开导入 = ref(false);
const 文件输入 = ref<HTMLInputElement | null>(null);
const 当前预设 = ref<string | null>(null);

const 已导入 = computed(() => store.workspace.imports);
const 可导入 = computed(() => store.availablePresetNames);

function 条目数(id: string): number {
  const imported = 已导入.value.find(i => i.id === id);
  return imported ? store.条目(imported).length : 0;
}

/** 该预设是不是当前槽位的骨架 */
function 槽位骨架判断(id: string): boolean {
  return store.slot.skeletonId === id;
}

/** 该预设里有多少条目已经进了当前槽位 */
function 已缝数(id: string): number {
  const imported = 已导入.value.find(i => i.id === id);
  if (!imported) return 0;
  return store.条目(imported).filter(p => store.targetUidSet.has(`${id}::${p.id}`)).length;
}

function 选中(id: string) {
  当前预设.value = id;
  emit('选中预设', id);
}

function 从酒馆导入(name: string) {
  const imported = store.importFromTavern(name);
  if (imported) {
    展开导入.value = false;
    选中(imported.id);
  }
}

function 刷新(id: string) {
  if (store.refreshSnapshot(id)) toastr.success('已重新拉取快照', '预设缝合助手');
}

/** 一键清空全部已导入的源预设 */
function 清空导入() {
  const 确认 = confirm(`确定清空全部 ${已导入.value.length} 个已导入的预设吗？引用它们的目标条目会一并清掉。`);
  if (!确认) return;
  store.清空已导入预设();
  当前预设.value = null;
  emit('选中预设', '');
  toastr.success('已清空全部导入的预设', '预设缝合助手');
}

function 移除(id: string) {
  store.removeImport(id);
  if (当前预设.value === id) {
    当前预设.value = null;
    emit('选中预设', '');
  }
}

/** 进入该预设的批量选择模式 */
function 批量(id: string) {
  选中(id);
  批量模式.value = true;
}

async function 选文件(event: Event) {
  const input = event.target as HTMLInputElement;
  const file = input.files?.[0];
  input.value = '';
  if (!file) return;
  const imported = store.importFromJson(file.name.replace(/\.json$/i, ''), await file.text());
  if (imported) {
    展开导入.value = false;
    选中(imported.id);
  }
}
</script>

<template>
  <div class="flex flex-col flex-1 min-h-0">
    <div class="p-2 border-b border-line shrink-0">
      <div class="flex gap-1">
        <button
          class="flex-1 px-2 py-1.5 rounded-md text-xs border border-line hover:border-accent hover:text-accent transition-colors"
          @click="展开导入 = !展开导入"
        >
          <i class="fa-solid fa-plus mr-1" />{{ 展开导入 ? '收起' : '导入预设' }}
        </button>
        <button
          class="px-2 py-1.5 rounded-md text-xs border border-line hover:border-danger hover:text-danger transition-colors disabled:opacity-35"
          :disabled="已导入.length === 0"
          title="清空全部已导入的源预设（会一并清掉引用它们的目标条目）"
          @click="清空导入"
        >
          <i class="fa-solid fa-trash-can" />
        </button>
      </div>
    </div>

    <!-- 导入选择器 -->
    <div v-if="展开导入" class="p-2 border-b border-line glass-strong shrink-0 max-h-64 overflow-y-auto">
      <div class="text-xs text-muted mb-1">从酒馆同步</div>
      <div v-if="可导入.length === 0" class="text-xs text-muted mb-2">没有可导入的预设</div>
      <button
        v-for="name in 可导入"
        :key="name"
        class="block w-full text-left px-2 py-1 rounded hover:bg-surface2 truncate text-xs"
        @click="从酒馆导入(name)"
      >
        {{ name }}
      </button>

      <div class="text-xs text-muted mt-3 mb-1">导入 JSON 文件</div>
      <button class="w-full px-2 py-1 rounded bg-surface2 hover:bg-line text-xs" @click="文件输入?.click()">
        选择文件…
      </button>
      <input ref="文件输入" type="file" accept=".json" class="hidden" @change="选文件" />
    </div>

    <!-- 已导入列表 -->
    <div class="flex-1 overflow-y-auto">
      <div v-if="已导入.length === 0" class="p-3 text-xs text-muted leading-relaxed">
        还没有导入预设。<br />点上方按钮从酒馆同步，或导入 JSON 文件。
      </div>

      <div
        v-for="item in 已导入"
        :key="item.id"
        class="px-2 py-1.5 border-b border-line/50 cursor-pointer transition-colors"
        :class="当前预设 === item.id ? 'bg-surface2' : 'hover:bg-surface/50'"
        @click="选中(item.id)"
      >
        <div class="flex items-center gap-1.5">
          <span
            class="cursor-pointer text-sm leading-none"
            :class="槽位骨架判断(item.id) ? 'text-warn' : 'text-muted hover:text-warn'"
            :title="槽位骨架判断(item.id) ? '当前槽位的骨架' : '点此设为当前槽位的骨架'"
            @click.stop="store.setSkeleton(item.id)"
          >
            {{ 槽位骨架判断(item.id) ? '★' : '☆' }}
          </span>
          <span class="truncate flex-1 text-xs">{{ item.name }}</span>
          <span v-if="已缝数(item.id)" class="text-[10px] text-accent shrink-0" title="已缝入当前槽位的条目数">
            缝{{ 已缝数(item.id) }}
          </span>
          <span class="text-[10px] text-muted shrink-0">{{ 条目数(item.id) }}</span>
        </div>

        <div class="flex items-center gap-1.5 text-[10px] text-muted pl-5 mt-0.5">
          <span class="opacity-70">{{ item.source === 'tavern' ? '酒馆' : '文件' }}</span>
          <button
            v-if="item.source === 'tavern'"
            class="hover:text-accent transition-colors"
            title="重新从源预设拉取快照"
            @click.stop="刷新(item.id)"
          >
            <i class="fa-solid fa-rotate" /> 拉取
          </button>
          <button
            class="hover:text-accent transition-colors"
            title="批量选择该预设的条目"
            @click.stop="批量(item.id)"
          >
            <i class="fa-solid fa-list-check" /> 批量
          </button>
          <button
            class="hover:text-danger transition-colors ml-auto"
            title="移除该预设（不影响源预设）"
            @click.stop="移除(item.id)"
          >
            <i class="fa-solid fa-trash-can" />
          </button>
        </div>
      </div>
    </div>

  </div>
</template>
